function validStorePrivacyDisclosureReport(reviewId: string, overrides: Record<string, unknown> = {}) {
  const signals = Object.fromEntries(STORE_PRIVACY_DISCLOSURE_REQUIRED_SIGNALS_FOR_TESTS.map((signal) => [signal, true]));
  return {
    schemaVersion: "freed-store-privacy-disclosure-report-v1",
    sanitized: true,
    result: "privacy-disclosure-review-captured",
    privacyDisclosureProofUsableForManualEvidence: true,
    reviewId,
    platformsReviewed: ["ios", "android"],
    reviewedStoreSurfaces: [
      "app-store-connect-app-privacy",
      "play-console-data-safety",
      "app-review-notes",
      "play-policy-declarations"
    ],
    suggestedEvidenceFields: ["store.privacyDisclosureArtifact"],
    privacyDataMapPath: "docs/privacy-data-map.md",
    privacyDataMapHash: sourceSha256Label("docs/privacy-data-map.md"),
    iosReviewPackPath: "docs/store-policy/ios-screen-time-safari-dns-review.md",
    iosReviewPackHash: sourceSha256Label("docs/store-policy/ios-screen-time-safari-dns-review.md"),
    androidPolicyPackPath: "docs/store-policy/android-accessibility-and-fgs-disclosure.md",
    androidPolicyPackHash: sourceSha256Label("docs/store-policy/android-accessibility-and-fgs-disclosure.md"),
    signals,
    checks: signals,
    ...overrides
  };
}

