function validStoreInterventionFlowReport(
  store: Record<string, unknown>,
  config: {
    artifactField: string;
    flowType: string;
    runIdField: string;
    latencyField?: string;
  },
  overrides: Record<string, unknown> = {}
) {
  const checks = Object.fromEntries(
    (STORE_INTERVENTION_FLOW_REQUIRED_CHECKS_FOR_TESTS[config.flowType] ?? []).map((check) => [check, true])
  );
  const report: Record<string, unknown> = {
    schemaVersion: "freed-store-intervention-flow-report-v1",
    sanitized: true,
    result: "intervention-flow-captured",
    interventionFlowProofUsableForManualEvidence: true,
    flowType: config.flowType,
    runId: store[config.runIdField],
    suggestedEvidenceFields: [`store.${config.artifactField}`],
    checks
  };
  if (config.latencyField) report.latencyMs = store[config.latencyField];
  if (config.flowType === "free-rewarded-intervention") {
    report.rewardedAdRequested = true;
    report.premiumEntitlementActive = false;
  }
  if (config.flowType === "rewarded-ad-completion") {
    report.rewardedAdCompleted = true;
    report.challengeAccessGranted = true;
  }
  if (config.flowType === "ad-failure-fallback") {
    report.adFailureObserved = true;
    report.challengeAccessGranted = true;
    report.retryLoopRequired = false;
  }
  if (config.flowType === "premium-no-ad-intervention") {
    report.premiumEntitlementActive = true;
    report.rewardedAdRequested = false;
  }
  return { ...report, ...overrides };
}

