function writeZeroVulnerabilityNpmStub(fakeBinDir: string) {
  const fakeNpmPath = join(fakeBinDir, "npm");
  writeFileSync(
    fakeNpmPath,
    [
      "#!/usr/bin/env node",
      "const releaseAuditOutputs = {",
      "  'audit:classifier': 'Result: 49 pass, 0 fail',",
      "  'audit:android-classifier': 'Result: 15 pass, 0 fail',",
      "  'audit:privacy': 'Result: 31 pass, 0 fail',",
      "  'audit:backend': 'Result: 16 pass, 0 fail',",
      "  'audit:smoke-harnesses': 'Result: 94 pass, 0 fail',",
      "  'audit:store-catalog': JSON.stringify({ result: 'pass' }),",
      "  'audit:eas-workflows': 'Result: 14 pass, 0 fail',",
      "  'audit:firebase-config': 'Result: pass',",
      "  'audit:store-legal': JSON.stringify({ result: 'pass' })",
      "};",
      "const releaseAuditOutput = releaseAuditOutputs[process.argv.at(-1)];",
      "if (releaseAuditOutput) {",
      "  console.log(releaseAuditOutput);",
      "  process.exit(0);",
      "}",
      "if (process.argv.includes('audit')) {",
      "  console.log(JSON.stringify({",
      "    auditReportVersion: 2,",
      "    vulnerabilities: {},",
      "    metadata: { vulnerabilities: { info: 0, low: 0, moderate: 0, high: 0, critical: 0, total: 0 } }",
      "  }));",
      "  process.exit(0);",
      "}",
      "console.error('unexpected npm command');",
      "process.exit(1);"
    ].join("\n")
  );
  chmodSync(fakeNpmPath, 0o755);
}

function runReleaseReadinessAudit(extraEnv: Record<string, string> = {}, args: string[] = []) {
  const hasCustomPath = Object.prototype.hasOwnProperty.call(extraEnv, "PATH");
  const fakeBinDir = hasCustomPath ? "" : mkdtempSync(join(tmpdir(), "freed-zero-audit-npm-"));

  try {
    if (fakeBinDir) writeZeroVulnerabilityNpmStub(fakeBinDir);
    const pathEnv = fakeBinDir
      ? `${fakeBinDir}:${dirname(process.execPath)}:${process.env.PATH ?? ""}`
      : process.env.PATH ?? "";

    return execFileSync(process.execPath, ["--", join(process.cwd(), "scripts/run-ts-entry.js"), "scripts/release-readiness.ts", ...args], {
      cwd: process.cwd(),
      encoding: "utf8",
      env: childToolEnv({ PATH: pathEnv, ...extraEnv }),
      stdio: ["ignore", "pipe", "pipe"],
      timeout: CORE_TEST_CHILD_TIMEOUT_MS
    });
  } finally {
    if (fakeBinDir) rmSync(fakeBinDir, { recursive: true, force: true });
  }
}

