  const sourceConfigWithPhysicalLineIssue = [
    "oisd-nsfw|OISD NSFW|https://feeds.freedrecovery.app/oisd.txt",
    "# reviewed custom source follows after this spacer",
    "",
    "bad-line-without-url",
    "freed-custom|FREED Custom|https://feeds.freedrecovery.app/custom.txt"
  ].join("\n");
