  assert.equal(safeHostSearchAttempt.result.matchedRule, "safe-site-search:porn");
  assert.equal(rawAdultUrlAttempt.url, "https://pornhub.com");
  assert.equal(rawAdultUrlAttempt.host, "pornhub.com");
  assert.equal(safeHostSearchAttempt.sourcePackage, undefined);
  assert.equal(rawAdultUrlAttempt.sourcePackage, undefined);
