  assert.match(readFileSync("modules/freed-protection/android/src/main/java/app/freed/protection/FreedDoomscrollApps.kt", "utf8"), /fun packageForShortFormRule\(rule: String\): String\?/);
  assert.match(readFileSync("modules/freed-protection/android/src/main/java/app/freed/protection/FreedProtectionModule.kt", "utf8"), /packageForShortFormRule\(rawSource\)/);
  assert.equal(unsupportedConfiguredApp.source, "app");
