test("challenge verification requires real movement for physical and outdoor resets", () => {
  const physical = getChallengeVerificationRequirement({
    id: "pushups-20",
    title: "20 controlled pushups",
    category: "physical",
    durationSec: 90,
    intensity: "strong",
    premium: false,
    icon: "Dumbbell",
    why: "Physical effort changes state.",
    steps: ["Plant your hands.", "Lower slowly."]
  });
  const outdoor = getChallengeVerificationRequirement({
    id: "walk-outside",
    title: "Walk outside for five minutes",
    category: "reset",
    durationSec: 300,
    intensity: "medium",
    premium: false,
    icon: "Footprints",
    why: "Changing environment breaks the cue loop.",
    steps: ["Step outside.", "Walk around your building."]
  });
  const indoorWalk = getChallengeVerificationRequirement({
    id: "walk-room",
    title: "Walk 40 steps around your room",
    category: "reset",
    durationSec: 120,
    intensity: "medium",
    premium: false,
    icon: "Footprints",
    why: "A short walk breaks the loop without collecting location.",
    steps: ["Carry the phone.", "Walk around the room until the counter moves."]
  });
  const photo = getChallengeVerificationRequirement({
    id: "flower-photo",
    title: "Take a photo of a flower nearby",
    category: "reset",
    durationSec: 60,
    intensity: "medium",
    premium: false,
    icon: "Camera",
    why: "A specific visual target pulls attention into the real world.",
    steps: ["Find a flower.", "Take a fresh camera photo."]
  });
  const breathing = getChallengeVerificationRequirement({
    id: "breathing-478",
    title: "4-7-8 breathing reset",
    category: "breathing",
    durationSec: 180,
    intensity: "calm",
    premium: false,
    icon: "Waves",
    why: "Slow breathing lowers arousal.",
    steps: ["Inhale.", "Exhale."]
  });
  const connection = getChallengeVerificationRequirement({
    id: "trusted-person",
    title: "Reach out to a trusted person",
    category: "connection",
    durationSec: 90,
    intensity: "calm",
    premium: false,
    icon: "MessageCircleHeart",
    why: "A real connection action breaks isolation.",
    steps: ["Send the check-in.", "Return to FREED."]
  });

  assert.equal(physical.kind, "motion");
  assert.equal(outdoor.kind, "location");
  assert.equal(outdoor.minLocationSamples, 2);
  assert.equal(outdoor.maxLocationAccuracyMeters, 80);
  assert.equal(indoorWalk.kind, "steps");
  assert.equal(photo.kind, "photo");
  assert.ok(photo.expectedPhotoLabels?.includes("flower"));
  assert.equal(photo.minPhotoConfidence, 0.45);
  assert.equal(breathing.kind, "timer");
  assert.equal(connection.kind, "connection");
  assert.match(connection.detail, /Complete the connection action/);
  assert.equal(isChallengeVerificationSatisfied(physical, { elapsedSec: 90, motionSamples: 0 }), false);
  assert.equal(isChallengeVerificationSatisfied(physical, { elapsedSec: 90, motionSamples: physical.minMotionSamples }), true);
  assert.equal(isChallengeVerificationSatisfied(outdoor, { elapsedSec: 300, distanceMeters: 3, locationSamples: 2, bestLocationAccuracyMeters: 20 }), false);
  assert.equal(isChallengeVerificationSatisfied(outdoor, { elapsedSec: 300, distanceMeters: outdoor.minDistanceMeters, locationSamples: 1, bestLocationAccuracyMeters: 20 }), false);
  assert.equal(isChallengeVerificationSatisfied(outdoor, { elapsedSec: 300, distanceMeters: outdoor.minDistanceMeters, locationSamples: 2, bestLocationAccuracyMeters: 120 }), false);
  assert.equal(isChallengeVerificationSatisfied(outdoor, { elapsedSec: 300, distanceMeters: outdoor.minDistanceMeters, locationSamples: 2, bestLocationAccuracyMeters: 20 }), true);
  assert.equal(isChallengeVerificationSatisfied(indoorWalk, { elapsedSec: 120, steps: 0 }), false);
  assert.equal(isChallengeVerificationSatisfied(indoorWalk, { elapsedSec: 120, steps: indoorWalk.minSteps }), true);
  assert.equal(isChallengeVerificationSatisfied(photo, { elapsedSec: 60, photoMatched: false }), false);
  assert.equal(isChallengeVerificationSatisfied(photo, { elapsedSec: 60, photoMatched: true, photoLabels: ["flower"], photoConfidence: 0.32 }), false);
  assert.equal(isChallengeVerificationSatisfied(photo, { elapsedSec: 60, photoMatched: true, photoLabels: ["car"], photoConfidence: 0.92 }), false);
  assert.equal(isChallengeVerificationSatisfied(photo, { elapsedSec: 60, photoMatched: true, photoLabels: ["flower"], photoConfidence: 0.88 }), true);
  assert.equal(isChallengeVerificationSatisfied(connection, { elapsedSec: 90, connectionActionComplete: false }), false);
  assert.equal(isChallengeVerificationSatisfied(connection, { elapsedSec: 90, connectionActionComplete: true }), true);
  assert.equal(Math.round(distanceMeters({ latitude: 0, longitude: 0 }, { latitude: 0, longitude: 0.001 })), 111);
});

