test("challenge generation readiness reports missing remote configuration", () => {
  const previousMode = process.env.EXPO_PUBLIC_AI_CHALLENGE_MODE;
  const previousEndpoint = process.env.EXPO_PUBLIC_AI_CHALLENGE_ENDPOINT;

  try {
    process.env.EXPO_PUBLIC_AI_CHALLENGE_MODE = "remote";
    delete process.env.EXPO_PUBLIC_AI_CHALLENGE_ENDPOINT;
    configureChallengeGenerationProvider(null);

    const readiness = getChallengeGenerationReadiness();
    assert.equal(readiness.status, "missing-config");
    assert.ok(readiness.missing.includes("remote challenge provider or endpoint"));

    process.env.EXPO_PUBLIC_AI_CHALLENGE_ENDPOINT = "http://localhost:3000/api/challenges";
    const unsafeReadiness = getChallengeGenerationReadiness();
    assert.equal(unsafeReadiness.status, "missing-config");
    assert.ok(unsafeReadiness.missing.includes("must use HTTPS"));
    assert.ok(unsafeReadiness.missing.includes("must not point to a local development host"));
  } finally {
    restoreEnv("EXPO_PUBLIC_AI_CHALLENGE_MODE", previousMode);
    restoreEnv("EXPO_PUBLIC_AI_CHALLENGE_ENDPOINT", previousEndpoint);
  }
});

test("production endpoint safety rejects local or insecure AI endpoints", () => {
  assert.deepEqual(getProductionEndpointIssues("https://api.freedrecovery.app/api/clara", "coach"), []);
  assert.deepEqual(getProductionBaseUrlIssues("https://freed-project.supabase.co", "Supabase Auth base URL"), []);
  assert.deepEqual(formatEndpointIssues(getProductionBaseUrlIssues("https://freed-project.supabase.co?token=secret", "Supabase Auth base URL")), [
    "Supabase Auth base URL must not include query strings"
  ]);
  assert.deepEqual(formatEndpointIssues(getProductionBaseUrlIssues("https://freed-project.supabase.co#access_token=secret", "Supabase Auth base URL")), [
    "Supabase Auth base URL must not include URL fragments"
  ]);
  assert.deepEqual(formatEndpointIssues(getProductionBaseUrlIssues("https://freed-project.supabase.co/rest/v1", "Supabase Auth base URL")), [
    "Supabase Auth base URL must be an origin without a path"
  ]);
  assert.deepEqual(formatEndpointIssues(getProductionEndpointIssues("http://localhost:8081/api/clara", "coach")), [
    "coach must use HTTPS",
    "coach must not point to a local development host"
  ]);
  assert.deepEqual(formatEndpointIssues(getProductionEndpointIssues("https://api.freedrecovery.app", "coach")), [
    "coach must include a concrete API route path"
  ]);
  assert.deepEqual(formatEndpointIssues(getProductionEndpointIssues("https://user:pass@api.freedrecovery.app/api/clara", "coach")), [
    "coach must not include URL credentials"
  ]);
  assert.deepEqual(formatEndpointIssues(getProductionEndpointIssues("https://api.freedrecovery.app/api/clara?token=secret", "coach")), [
    "coach must not include query strings"
  ]);
  assert.deepEqual(formatEndpointIssues(getProductionEndpointIssues("https://api.freedrecovery.app/api/clara#access_token=secret", "coach")), [
    "coach must not include URL fragments"
  ]);
  assert.deepEqual(formatEndpointIssues(getProductionEndpointIssues("https://your-deployed-origin.example/api/clara", "coach")), [
    "coach must not use a placeholder or documentation host"
  ]);
  assert.deepEqual(formatEndpointIssues(getProductionEndpointIssues("https://your-api.freedrecovery.app/api/clara", "coach")), [
    "coach must not use a placeholder or documentation host"
  ]);
  assert.deepEqual(formatEndpointIssues(getProductionEndpointIssues("https://api.internal/api/clara", "coach")), [
    "coach must not point to a local development host"
  ]);
  assert.deepEqual(formatEndpointIssues(getProductionEndpointIssues("https://api.localhost/api/clara", "coach")), [
    "coach must not use a placeholder or documentation host"
  ]);
  assert.deepEqual(formatEndpointIssues(getProductionEndpointIssues("https://192.168.1.10/api/clara", "coach")), [
    "coach must not point to a private or reserved network address"
  ]);
  assert.deepEqual(formatEndpointIssues(getProductionEndpointIssues("https://198.18.0.1/api/clara", "coach")), [
    "coach must not point to a private or reserved network address"
  ]);
  assert.deepEqual(formatEndpointIssues(getProductionEndpointIssues("https://224.0.0.1/api/clara", "coach")), [
    "coach must not point to a private or reserved network address"
  ]);
  assert.deepEqual(formatEndpointIssues(getProductionEndpointIssues("https://[fd00::1]/api/clara", "coach")), [
    "coach must not point to a private or reserved network address"
  ]);
  assert.deepEqual(formatEndpointIssues(getProductionEndpointIssues("https://[::1]/api/clara", "coach")), [
    "coach must not point to a local development host",
    "coach must not point to a private or reserved network address"
  ]);
});

