test("recovery state hydrates legacy raw attempt URLs into redacted host-only entries", () => {
  const rawAttempt = {
    ...createBlockingAttempt("https://pornhub.com/watch", "browser"),
    url: "https://user:secret@www.pornhub.com:443/watch?private=path",
    host: "user:secret@www.pornhub.com:443/private/path?token=secret",
    result: {
      ...createBlockingAttempt("https://pornhub.com/watch", "browser").result,
      host: "www.pornhub.com:443/private/path?token=secret",
      reason: "Legacy reason echoed https://user:secret@private.example.com/raw?token=secret and access_token=abc123.",
      matchedRule: "legacy-rule:private.example.com/raw?token=secret access_token=abc123",
      rawUrl: "https://private.example.com/raw?token=secret"
    },
    source: "test-lab",
    rawUrl: "https://private.example.com/raw?token=secret",
    note: "private note should not survive hydration"
  };
  const hydrated = hydrateRecoveryState({
    ...createDefaultRecoveryState(),
    attempts: [rawAttempt]
  });
  const serialized = JSON.stringify(hydrated.attempts[0]);

  assert.equal(hydrated.attempts[0].url, "https://pornhub.com");
  assert.equal(hydrated.attempts[0].host, "pornhub.com");
  assert.equal(hydrated.attempts[0].result.host, "pornhub.com");
  assert.equal(Object.prototype.hasOwnProperty.call(hydrated.attempts[0], "rawUrl"), false);
  assert.equal(Object.prototype.hasOwnProperty.call(hydrated.attempts[0], "note"), false);
  assert.equal(Object.prototype.hasOwnProperty.call(hydrated.attempts[0].result, "rawUrl"), false);
  assert.equal(hydrated.attempts[0].source, "manual-check");
  assert.equal(serialized.includes("user:secret"), false);
  assert.equal(serialized.includes(":443"), false);
  assert.equal(serialized.includes("/watch"), false);
  assert.equal(serialized.includes("private note"), false);
  assert.equal(serialized.includes("private.example.com"), false);
  assert.equal(serialized.includes("access_token=abc123"), false);
  assert.equal(serialized.includes("token=secret"), false);
});

test("recovery state persists onboarding, premium mode, and challenge history shape", () => {
  const challenge = challengeLibrary[0];
  const onboarded = completeOnboarding(createDefaultRecoveryState(), ["Mental clarity", "Late night"]);
  const paywallPresented = markOnboardingPaywallPresented(onboarded, "2026-05-11T07:45:00.000Z");
  const activated = markProtectionActivated(paywallPresented, "android", "2026-05-11T07:55:00.000Z");
  const premium = setPremiumPlan(activated, true, "ai-coach", "2026-05-11T08:00:00.000Z");
  const completed = recordChallengeCompletion(premium, challenge, "2026-05-11T09:30:00.000Z", "pornhub.com");
  const hydrated = hydrateRecoveryState(JSON.parse(JSON.stringify(completed)));
  const activationCleared = clearProtectionActivation(hydrated);
  const legacyPremium = hydrateRecoveryState({
    ...createDefaultRecoveryState(),
    premium: true,
    premiumPlanId: "not-a-plan",
    premiumActivatedAt: "not-a-date"
  });
  const clearedPremium = setPremiumPlan(hydrated, false);

  assert.equal(hydrated.hasCompletedOnboarding, true);
  assert.equal(hydrated.onboardingPaywallPresentedAt, "2026-05-11T07:45:00.000Z");
  assert.equal(hydrated.protectionActivatedAt, "2026-05-11T07:55:00.000Z");
  assert.equal(hydrated.protectionActivationPlatform, "android");
  assert.equal(hasProtectionActivationForPlatform(hydrated, "android"), true);
  assert.equal(hasProtectionActivationForPlatform(hydrated, "ios"), false);
  assert.equal(hydrated.premium, true);
  assert.equal(hydrated.premiumPlanId, "ai-coach");
  assert.equal(hydrated.premiumPlanAudience, "coaching");
  assert.equal(hydrated.premiumActivatedAt, "2026-05-11T08:00:00.000Z");
  assert.deepEqual(hydrated.answers, ["Mental clarity", "Late night"]);
  assert.equal(hydrated.completedChallenges, createDefaultRecoveryState().completedChallenges + 1);
  assert.equal(hydrated.challengeHistory[0].id, challenge.id);
  assert.equal(hydrated.challengeHistory[0].outcome, "helped");
  assert.equal(hydrated.challengeHistory[0].sourceAttemptHost, "pornhub.com");
  assert.equal(legacyPremium.premium, true);
  assert.equal(legacyPremium.premiumPlanId, null);
  assert.equal(legacyPremium.premiumPlanAudience, null);
  assert.equal(legacyPremium.premiumActivatedAt, null);
  assert.equal(clearedPremium.premium, false);
  assert.equal(clearedPremium.premiumPlanId, null);
  assert.equal(clearedPremium.premiumActivatedAt, null);
  assert.equal(clearedPremium.protectionActivationPlatform, "android");
  assert.equal(activationCleared.protectionActivatedAt, null);
  assert.equal(activationCleared.protectionActivationPlatform, null);
  assert.equal(hasProtectionActivationForPlatform(activationCleared, "android"), false);
});

