test("challenge context uses check-ins and coarse real-weather inputs", () => {
  const context = buildChallengeContextSignals({
    mood: "low",
    urgeLevel: 4,
    sleepQuality: 2
  });
  const url = buildOpenMeteoWeatherUrl({ latitude: 37.7749, longitude: -122.4194 });
  const disabledConfig = getChallengeWeatherContextConfig({
    EXPO_PUBLIC_CHALLENGE_WEATHER_CONTEXT_ENABLED: "false"
  });
  const enabledConfig = getChallengeWeatherContextConfig({
    EXPO_PUBLIC_CHALLENGE_WEATHER_CONTEXT_ENABLED: "true",
    EXPO_PUBLIC_CHALLENGE_WEATHER_CONTEXT_ENDPOINT: "https://api.open-meteo.com/v1/forecast",
    EXPO_PUBLIC_CHALLENGE_WEATHER_CONTEXT_TIMEOUT_MS: "7000",
    EXPO_PUBLIC_CHALLENGE_WEATHER_CONTEXT_RESPONSE_MAX_BYTES: "64000"
  });
  const missingEndpointConfig = getChallengeWeatherContextConfig({
    EXPO_PUBLIC_CHALLENGE_WEATHER_CONTEXT_ENABLED: "true"
  });
  const unsafeEndpointConfig = getChallengeWeatherContextConfig({
    EXPO_PUBLIC_CHALLENGE_WEATHER_CONTEXT_ENABLED: "true",
    EXPO_PUBLIC_CHALLENGE_WEATHER_CONTEXT_ENDPOINT: "http://localhost:8080/weather"
  });
  const privateEndpointConfig = getChallengeWeatherContextConfig({
    EXPO_PUBLIC_CHALLENGE_WEATHER_CONTEXT_ENABLED: "true",
    EXPO_PUBLIC_CHALLENGE_WEATHER_CONTEXT_ENDPOINT: "https://192.168.1.50/weather"
  });
  const placeholderEndpointConfig = getChallengeWeatherContextConfig({
    EXPO_PUBLIC_CHALLENGE_WEATHER_CONTEXT_ENABLED: "true",
    EXPO_PUBLIC_CHALLENGE_WEATHER_CONTEXT_ENDPOINT: "https://your-weather.example/v1/forecast"
  });

  assert.equal(context.energyLevel, "low");
  assert.equal(context.urgeLevel, 4);
  assert.equal(context.sleepQuality, 2);
  assert.equal(context.weatherCondition, null);
  assert.equal(disabledConfig.enabled, false);
  assert.equal(enabledConfig.enabled, true);
  assert.equal(enabledConfig.endpointUrl, "https://api.open-meteo.com/v1/forecast");
  assert.equal(enabledConfig.timeoutMs, 7000);
  assert.equal(enabledConfig.responseMaxBytes, 64000);
  assert.equal(missingEndpointConfig.enabled, false);
  assert.equal(missingEndpointConfig.endpointUrl, null);
  assert.equal(unsafeEndpointConfig.enabled, false);
  assert.equal(unsafeEndpointConfig.endpointUrl, null);
  assert.equal(privateEndpointConfig.enabled, false);
  assert.equal(privateEndpointConfig.endpointUrl, null);
  assert.equal(placeholderEndpointConfig.enabled, false);
  assert.equal(placeholderEndpointConfig.endpointUrl, null);
  assert.equal(permissionStatusToChallengeSignal("granted"), "granted");
  assert.equal(permissionStatusToChallengeSignal("blocked"), "unknown");
  assert.equal(weatherCodeToCondition(61, 12), "rain");
  assert.equal(weatherCodeToCondition(0, 36), "hot");
  assert.ok(url);
  assert.match(url, /latitude=37\.8/);
  assert.match(url, /longitude=-122\.4/);
  assert.equal(url.includes("37.7749"), false);
  assert.equal(url.includes("-122.4194"), false);
});

