test("notification response listener loads native notifications only after reminders are enabled", () => {
  const appSurface = readFileSync("src/features/freed-app.tsx", "utf8");
  const listenerIndex = appSurface.indexOf("listenForReminderResponses((route)");
  const listenerEffect = appSurface.slice(appSurface.lastIndexOf("React.useEffect", listenerIndex), listenerIndex + 360);
  const nativeInterventionIndex = appSurface.indexOf("consumePendingIntervention();");
  const nativeInterventionEffect = appSurface.slice(appSurface.lastIndexOf("React.useEffect", nativeInterventionIndex), nativeInterventionIndex + 240);

  assert.ok(listenerIndex > 0);
  assert.match(listenerEffect, /if \(!hydrated \|\| !reminders\.enabled\) return undefined;/);
  assert.doesNotMatch(nativeInterventionEffect, /!reminders\.enabled/);
  assert.match(appSurface, /\}, \[hydrated, reminders\.enabled\]\);/);
});

