  assert.equal(androidStaleDnsRuntimePlan.find((step) => step.id === "android-dns-guard")?.status, "needed");
  assert.equal(getProtectionPermissionProgress(androidStaleDnsRuntimePlan).ready, false);
  assert.match(PROTECTION_PERMISSION_EXPLANATION, /explicit content and doomscroll loops/);
  assert.match(PROTECTION_PERMISSION_EXPLANATION, /monitor only selected apps and sites/);
  assert.match(PROTECTION_PERMISSION_EXPLANATION, /block known adult domains/);
