test("protection setup readiness requires platform-native app timer proof", () => {
  const iosCapability = {
    platform: "ios" as const,
    screenTime: true,
    managedSettings: true,
    accessibility: false,
    dnsFiltering: true,
    safariContentBlocker: true,
    localVpnFallback: false,
    notes: []
  };
  const androidCapability = {
    platform: "android" as const,
    screenTime: false,
    managedSettings: false,
    accessibility: true,
    dnsFiltering: true,
    usageStats: true,
    localVpnFallback: true,
    notes: []
  };
  const androidMissingCapability = {
    platform: "android" as const,
    screenTime: false,
    managedSettings: false,
    accessibility: false,
    dnsFiltering: false,
    usageStats: false,
    localVpnFallback: false,
    notes: []
  };
  const iosMissingSafariCapability = {
    platform: "ios" as const,
    screenTime: true,
    managedSettings: true,
    accessibility: false,
    dnsFiltering: true,
    localVpnFallback: false,
    notes: []
  };
  const iosMissingCapability = {
    platform: "ios" as const,
    screenTime: false,
    managedSettings: false,
    accessibility: false,
    dnsFiltering: true,
    safariContentBlocker: false,
    localVpnFallback: false,
    notes: []
  };

  const iosWithoutScheduledLimit = getProtectionSetupReadiness(
    iosCapability,
    {
      authorized: true,
      active: true,
      adultFilterActive: true,
      selectedApplications: 1,
      selectedCategories: 0,
      selectedWebDomains: 0,
      appLimitScheduled: false,
      safariContentBlockerEnabled: true,
      safariContentBlockerRuleCount: 1200,
      mode: "screen-time",
      message: "missing selected app limit"
    },
    1
  );
  const iosReady = getProtectionSetupReadiness(
    iosCapability,
    {
      authorized: true,
      active: true,
      adultFilterActive: true,
      selectedApplications: 1,
      selectedCategories: 0,
      selectedWebDomains: 0,
      appLimitScheduled: true,
      safariContentBlockerEnabled: true,
      safariContentBlockerRuleCount: 1200,
      mode: "screen-time",
      message: "ready"
    },
    1
  );
  const iosAggregateOnlyReady = getProtectionSetupReadiness(
    iosCapability,
    {
      authorized: true,
      active: true,
      adultFilterActive: true,
      selectedScreenTimeTokenCount: 2,
      appLimitScheduled: true,
      safariContentBlockerEnabled: true,
      safariContentBlockerRuleCount: 1200,
      mode: "screen-time",
      message: "ready with aggregate selected-token count"
    },
    1
  );
  const iosReadyStatusWithoutSafariCapability = getProtectionSetupReadiness(
    iosMissingSafariCapability,
    {
      authorized: true,
      active: true,
      adultFilterActive: true,
      selectedScreenTimeTokenCount: 2,
      appLimitScheduled: true,
      safariContentBlockerEnabled: true,
      safariContentBlockerRuleCount: 1200,
      mode: "screen-time",
      message: "ready-looking status without Safari target capability proof"
    },
    1
  );
  const iosStaleStatusWithoutCapabilities = getProtectionSetupReadiness(
    iosMissingCapability,
    {
      authorized: true,
      active: true,
      adultFilterActive: true,
      selectedApplications: 1,
      selectedCategories: 1,
      selectedWebDomains: 1,
      selectedScreenTimeTokenCount: 3,
      appLimitScheduled: true,
      safariContentBlockerEnabled: true,
      safariContentBlockerRuleCount: 1200,
      mode: "screen-time",
      message: "stale ready-looking status"
    },
    1
  );
  const androidWithoutNativePackages = getProtectionSetupReadiness(
    androidCapability,
    {
      authorized: true,
      active: true,
      adultFilterActive: true,
      dnsGuardRuntimeReady: true,
      appInterventionAuthorized: true,
      usageStatsAuthorized: true,
      blockedApplications: 0,
      adultDomainFeedDomainCount: 1200,
      mode: "dns",
      message: "permissions without configured packages"
    },
    2
  );
  const androidReady = getProtectionSetupReadiness(
    androidCapability,
    {
      authorized: true,
      active: true,
      adultFilterActive: true,
      dnsGuardRuntimeReady: true,
      appInterventionAuthorized: true,
      usageStatsAuthorized: true,
      blockedApplications: 2,
      adultDomainFeedDomainCount: 1200,
      mode: "dns",
      message: "ready"
    },
    2
  );
  const androidStaleScreenTimeModeReady = getProtectionSetupReadiness(
    androidCapability,
    {
      authorized: true,
      active: true,
      appInterventionAuthorized: true,
      usageStatsAuthorized: true,
      blockedApplications: 2,
      adultDomainFeedDomainCount: 1200,
      mode: "screen-time",
      message: "ready-looking status with stale iOS mode"
    },
    2
  );
  const androidStaleStatusWithoutCapabilities = getProtectionSetupReadiness(
    androidMissingCapability,
    {
      authorized: true,
      active: true,
      adultFilterActive: true,
      dnsGuardRuntimeReady: true,
      appInterventionAuthorized: true,
      usageStatsAuthorized: true,
      blockedApplications: 2,
      adultDomainFeedDomainCount: 1200,
      mode: "dns",
      message: "stale ready-looking Android status"
    },
    2
  );

  assert.equal(iosWithoutScheduledLimit.appInterventionReady, false);
  assert.equal(iosWithoutScheduledLimit.activationReady, false);
  assert.equal(iosReady.appInterventionReady, true);
  assert.equal(iosReady.activationReady, true);
  assert.equal(iosAggregateOnlyReady.selectedIosTargets, 2);
  assert.equal(iosAggregateOnlyReady.appInterventionReady, true);
  assert.equal(iosAggregateOnlyReady.activationReady, true);
  assert.equal(iosReadyStatusWithoutSafariCapability.permissionProgress.ready, false);
  assert.equal(iosReadyStatusWithoutSafariCapability.adultFilterActive, true);
  assert.equal(iosReadyStatusWithoutSafariCapability.appInterventionReady, true);
  assert.equal(iosReadyStatusWithoutSafariCapability.activationReady, false);
  assert.equal(iosStaleStatusWithoutCapabilities.permissionProgress.ready, false);
  assert.equal(iosStaleStatusWithoutCapabilities.adultFilterActive, false);
  assert.equal(iosStaleStatusWithoutCapabilities.appInterventionReady, false);
  assert.equal(iosStaleStatusWithoutCapabilities.activationReady, false);
  assert.equal(androidWithoutNativePackages.appInterventionReady, false);
  assert.equal(androidWithoutNativePackages.appCount, 2);
  assert.equal(androidWithoutNativePackages.nativeConfiguredAppCount, 0);
  assert.equal(androidWithoutNativePackages.activationReady, false);
  assert.equal(androidReady.appInterventionReady, true);
  assert.equal(androidReady.nativeConfiguredAppCount, 2);
  assert.equal(androidReady.activationReady, true);
  const previousReviewedFeedRequirement = process.env.EXPO_PUBLIC_REQUIRE_REVIEWED_ADULT_DOMAIN_FEED;
  try {
    process.env.EXPO_PUBLIC_REQUIRE_REVIEWED_ADULT_DOMAIN_FEED = "true";
    const androidEmbeddedFeedInProduction = getProtectionSetupReadiness(
      androidCapability,
      {
        authorized: true,
        active: true,
        adultFilterActive: true,
        dnsGuardRuntimeReady: true,
        appInterventionAuthorized: true,
        usageStatsAuthorized: true,
        blockedApplications: 2,
        adultDomainFeedVersion: "freed-embedded-2026-05-19",
        adultDomainFeedDomainCount: 1200,
        mode: "dns",
        message: "embedded feed only"
      },
      2
    );
    const androidReviewedFeedInProduction = getProtectionSetupReadiness(
      androidCapability,
      {
        authorized: true,
        active: true,
        adultFilterActive: true,
        dnsGuardRuntimeReady: true,
        appInterventionAuthorized: true,
        usageStatsAuthorized: true,
        blockedApplications: 2,
        adultDomainFeedVersion: "freed-feed-2026-05-22",
        adultDomainFeedDomainCount: 1200,
        mode: "dns",
        message: "reviewed feed"
      },
      2
    );

    assert.equal(androidEmbeddedFeedInProduction.permissionProgress.ready, false);
    assert.equal(androidEmbeddedFeedInProduction.nativeAdultFeedCount, 0);
    assert.equal(androidEmbeddedFeedInProduction.adultFilterActive, true);
    assert.equal(androidEmbeddedFeedInProduction.appInterventionReady, true);
    assert.equal(androidEmbeddedFeedInProduction.activationReady, false);
    assert.equal(androidReviewedFeedInProduction.permissionProgress.ready, true);
    assert.equal(androidReviewedFeedInProduction.nativeAdultFeedCount, 1200);
    assert.equal(androidReviewedFeedInProduction.activationReady, true);
  } finally {
    restoreEnv("EXPO_PUBLIC_REQUIRE_REVIEWED_ADULT_DOMAIN_FEED", previousReviewedFeedRequirement);
  }
  assert.equal(androidStaleScreenTimeModeReady.permissionProgress.ready, false);
  assert.equal(androidStaleScreenTimeModeReady.adultFilterActive, false);
  assert.equal(androidStaleScreenTimeModeReady.appInterventionReady, true);
  assert.equal(androidStaleScreenTimeModeReady.activationReady, false);
  assert.equal(androidStaleStatusWithoutCapabilities.permissionProgress.ready, false);
  assert.equal(androidStaleStatusWithoutCapabilities.adultFilterActive, false);
  assert.equal(androidStaleStatusWithoutCapabilities.nativeAdultFeedCount, 0);
  assert.equal(androidStaleStatusWithoutCapabilities.appInterventionReady, false);
  assert.equal(androidStaleStatusWithoutCapabilities.activationReady, false);
});

