test("premium plans expose stable product identifiers", () => {
  assert.deepEqual(
    PREMIUM_PLANS.map((plan) => plan.id),
    ["yearly", "monthly", "lifetime", "family", "accountability", "ai-coach"]
  );
  assert.deepEqual([...LAUNCH_PREMIUM_PLAN_IDS], ["yearly", "monthly", "lifetime"]);
  assert.deepEqual(getLaunchPremiumPlans().map((plan) => plan.id), ["yearly", "monthly", "lifetime"]);
  assert.equal(getLaunchPremiumPlan("yearly")?.productId, "freed_premium_yearly");
  assert.equal(getLaunchPremiumPlan("family"), null);
  assert.equal(isLaunchPremiumPlanId("monthly"), true);
  assert.equal(isLaunchPremiumPlanId("ai-coach"), false);
  assert.equal(getPremiumPlan("yearly")?.productId, "freed_premium_yearly");
  assert.equal(getPremiumPlan("family")?.productId, "freed_family_yearly");
  assert.equal(getPremiumPlan("accountability")?.productId, "freed_accountability_monthly");
  assert.equal(getPremiumPlan("ai-coach")?.productId, "freed_ai_coach_monthly");
  assert.equal(getPremiumPlan("family")?.audience, "family");
  assert.equal(getPremiumPlan("accountability")?.audience, "accountability");
  assert.equal(getPremiumPlan("ai-coach")?.audience, "coaching");
  assert.equal(getPremiumPlan("unknown"), null);
  assert.equal(LAUNCH_PREMIUM_PLAN_ECONOMICS.schemaVersion, "freed-launch-economics-v1");
  assert.equal(LAUNCH_PREMIUM_PLAN_ECONOMICS.conservativeStoreFeePercent, 30);
  assert.equal(LAUNCH_PREMIUM_PLAN_ECONOMICS.optimizedStoreFeePercent, 15);
  assert.equal(getLaunchPremiumPlanEconomics("monthly")?.estimatedNetUsdAt30PercentStoreFee, 6.99);
  assert.equal(getLaunchPremiumPlanEconomics("yearly")?.monthlyEquivalentGrossUsd, 3.33);
  assert.equal(getLaunchPremiumPlanEconomics("yearly")?.discountVsMonthlyPercent, 67);
  assert.equal(getLaunchPremiumPlanEconomics("yearly")?.profitabilityRole, "primary-value");
  assert.equal(getLaunchPremiumPlanEconomics("lifetime")?.breakevenMonthsVsMonthly, 8);
  assert.equal(getLaunchPremiumPlanEconomics("lifetime")?.breakevenYearsVsYearly, 2);
  assert.equal(getLaunchPremiumPlanEconomics("family"), null);

  const freeCapabilities = getPremiumCapabilities({ premium: false });
  const annualCapabilities = getPremiumCapabilities({ premium: true, planId: "yearly" });
  const familyCapabilities = getPremiumCapabilities({ premium: true, planId: "family" });
  const accountabilityCapabilities = getPremiumCapabilities({ premium: true, planId: "accountability" });
  const aiCoachCapabilities = getPremiumCapabilities({ premium: true, planId: "ai-coach" });

  assert.equal(freeCapabilities.noAds, false);
  assert.equal(freeCapabilities.premiumChallenges, false);
  assert.equal(annualCapabilities.noAds, true);
  assert.equal(annualCapabilities.premiumChallenges, true);
  assert.equal(annualCapabilities.advancedAnalytics, true);
  assert.equal(familyCapabilities.familySupport, true);
  assert.equal(familyCapabilities.sponsorAccountability, true);
  assert.equal(accountabilityCapabilities.sponsorAccountability, true);
  assert.equal(accountabilityCapabilities.familySupport, false);
  assert.equal(aiCoachCapabilities.relapsePrediction, true);
  assert.equal(aiCoachCapabilities.deepRecoveryReports, true);
});

test("monetization defaults to native fail-closed mode unless mock is explicit", () => {
  const previousMode = process.env.EXPO_PUBLIC_MONETIZATION_MODE;
  const previousNodeEnv = process.env.NODE_ENV;

  try {
    delete process.env.EXPO_PUBLIC_MONETIZATION_MODE;
    delete process.env.NODE_ENV;
    assert.equal(getMonetizationConfig().mode, "native");

    process.env.EXPO_PUBLIC_MONETIZATION_MODE = "mock";
    assert.equal(getMonetizationConfig().mode, "mock");

    process.env.NODE_ENV = "production";
    assert.equal(getMonetizationConfig().mode, "native");
  } finally {
    restoreEnv("EXPO_PUBLIC_MONETIZATION_MODE", previousMode);
    restoreEnv("NODE_ENV", previousNodeEnv);
  }
});

