test("monetization config supports store and ad environment overrides", () => {
  const previous = {
    yearly: process.env.EXPO_PUBLIC_IAP_PRODUCT_YEARLY,
    monthly: process.env.EXPO_PUBLIC_IAP_PRODUCT_MONTHLY,
    lifetime: process.env.EXPO_PUBLIC_IAP_PRODUCT_LIFETIME,
    family: process.env.EXPO_PUBLIC_IAP_PRODUCT_FAMILY,
    accountability: process.env.EXPO_PUBLIC_IAP_PRODUCT_ACCOUNTABILITY,
    aiCoach: process.env.EXPO_PUBLIC_IAP_PRODUCT_AI_COACH,
    revenueCatIos: process.env.EXPO_PUBLIC_REVENUECAT_API_KEY_IOS,
    premiumEntitlement: process.env.EXPO_PUBLIC_PREMIUM_ENTITLEMENT_ID,
    entitlement: process.env.EXPO_PUBLIC_REVENUECAT_ENTITLEMENT_ID,
    purchaseVerifyEndpoint: process.env.EXPO_PUBLIC_PURCHASE_VERIFY_ENDPOINT,
    admobIos: process.env.EXPO_PUBLIC_ADMOB_APP_ID_IOS,
    rewardedIos: process.env.EXPO_PUBLIC_ADMOB_REWARDED_RESET_UNIT_ID_IOS,
    adCountryIos: process.env.EXPO_PUBLIC_ADMOB_REQUEST_COUNTRY_IOS,
    testAds: process.env.EXPO_PUBLIC_ADMOB_USE_TEST_ADS
  };

  try {
    process.env.EXPO_PUBLIC_IAP_PRODUCT_YEARLY = "prod_yearly";
    process.env.EXPO_PUBLIC_IAP_PRODUCT_MONTHLY = "prod_monthly";
    process.env.EXPO_PUBLIC_IAP_PRODUCT_LIFETIME = "prod_lifetime";
    process.env.EXPO_PUBLIC_IAP_PRODUCT_FAMILY = "prod_family";
    process.env.EXPO_PUBLIC_IAP_PRODUCT_ACCOUNTABILITY = "prod_accountability";
    process.env.EXPO_PUBLIC_IAP_PRODUCT_AI_COACH = "prod_ai_coach";
    process.env.EXPO_PUBLIC_REVENUECAT_API_KEY_IOS = "appl_live1234567890";
    process.env.EXPO_PUBLIC_PREMIUM_ENTITLEMENT_ID = "freed_premium";
    process.env.EXPO_PUBLIC_PURCHASE_VERIFY_ENDPOINT = "https://api.freedapp.com/iap/verify";
    process.env.EXPO_PUBLIC_ADMOB_APP_ID_IOS = "ca-app-pub-1234567890123456~1234567890";
    process.env.EXPO_PUBLIC_ADMOB_REWARDED_RESET_UNIT_ID_IOS = "ca-app-pub-1234567890123456/1234567890";
    process.env.EXPO_PUBLIC_ADMOB_REQUEST_COUNTRY_IOS = "us";
    process.env.EXPO_PUBLIC_ADMOB_USE_TEST_ADS = "false";

    const config = getMonetizationConfig({ mode: "native", platform: "ios" });
    const plans = getPremiumPlans({ mode: "native", platform: "ios" });

    assert.equal(config.revenueCatApiKey, "appl_live1234567890");
    assert.equal(config.revenueCatEntitlementId, "freed_premium");
    assert.equal(config.purchaseVerifyEndpoint, "https://api.freedapp.com/iap/verify");
    assert.equal(config.admobAppId, "ca-app-pub-1234567890123456~1234567890");
    assert.equal(config.rewardedResetPlacementId, "ca-app-pub-1234567890123456/1234567890");
    assert.equal(config.adRequestCountryCode, "US");
    assert.deepEqual(config.launchProductIds, {
      yearly: "prod_yearly",
      monthly: "prod_monthly",
      lifetime: "prod_lifetime"
    });
    assert.equal(plans[0].productId, "prod_yearly");
    assert.equal(getPremiumPlan("monthly", { mode: "native", platform: "ios" })?.productId, "prod_monthly");
    assert.equal(getPremiumPlan("family", { mode: "native", platform: "ios" })?.productId, "prod_family");
    assert.equal(getPremiumPlan("accountability", { mode: "native", platform: "ios" })?.productId, "prod_accountability");
    assert.equal(getPremiumPlan("ai-coach", { mode: "native", platform: "ios" })?.productId, "prod_ai_coach");

    process.env.EXPO_PUBLIC_ADMOB_REQUEST_COUNTRY_IOS = "ZZ";
    assert.equal(getMonetizationConfig({ mode: "native", platform: "ios" }).adRequestCountryCode, null);
  } finally {
    restoreEnv("EXPO_PUBLIC_IAP_PRODUCT_YEARLY", previous.yearly);
    restoreEnv("EXPO_PUBLIC_IAP_PRODUCT_MONTHLY", previous.monthly);
    restoreEnv("EXPO_PUBLIC_IAP_PRODUCT_LIFETIME", previous.lifetime);
    restoreEnv("EXPO_PUBLIC_IAP_PRODUCT_FAMILY", previous.family);
    restoreEnv("EXPO_PUBLIC_IAP_PRODUCT_ACCOUNTABILITY", previous.accountability);
    restoreEnv("EXPO_PUBLIC_IAP_PRODUCT_AI_COACH", previous.aiCoach);
    restoreEnv("EXPO_PUBLIC_REVENUECAT_API_KEY_IOS", previous.revenueCatIos);
    restoreEnv("EXPO_PUBLIC_PREMIUM_ENTITLEMENT_ID", previous.premiumEntitlement);
    restoreEnv("EXPO_PUBLIC_REVENUECAT_ENTITLEMENT_ID", previous.entitlement);
    restoreEnv("EXPO_PUBLIC_PURCHASE_VERIFY_ENDPOINT", previous.purchaseVerifyEndpoint);
    restoreEnv("EXPO_PUBLIC_ADMOB_APP_ID_IOS", previous.admobIos);
    restoreEnv("EXPO_PUBLIC_ADMOB_REWARDED_RESET_UNIT_ID_IOS", previous.rewardedIos);
    restoreEnv("EXPO_PUBLIC_ADMOB_REQUEST_COUNTRY_IOS", previous.adCountryIos);
    restoreEnv("EXPO_PUBLIC_ADMOB_USE_TEST_ADS", previous.testAds);
  }
});

test("app config only injects Google Mobile Ads for production-format app ids", () => {
  const appConfig = readFileSync("app.config.js", "utf8");
  const androidRootBuildGradle = readFileSync("android/build.gradle", "utf8");
  const androidAppBuildGradle = readFileSync("android/app/build.gradle", "utf8");
  const androidManifest = readFileSync("android/app/src/main/AndroidManifest.xml", "utf8");
  const appJson = JSON.parse(readFileSync("app.json", "utf8")) as Record<string, unknown>;
  assert.match(appConfig, /function isValidAdMobAppId/);
  assert.match(appConfig, /\^ca-app-pub-\\d\{16\}~\\d\{10\}\$/);
  assert.match(appConfig, /ca-app-pub-3940256099942544/);
  assert.equal(Object.prototype.hasOwnProperty.call(appJson, "react-native-google-mobile-ads"), false);
  assert.match(androidRootBuildGradle, /freedGoogleMobileAdsLocalTestAppId = "ca-app-pub-3940256099942544~3347511713"/);
  assert.match(androidRootBuildGradle, /ext\.googleMobileAdsJson/);
  assert.match(androidRootBuildGradle, /react-native-google-mobile-ads/);
  assert.match(androidRootBuildGradle, /appJSONGoogleMobileAdsAppID\s*:\s*rootProject\.ext\.freedGoogleMobileAdsAndroidAppId/);
  assert.match(androidAppBuildGradle, /freedGoogleMobileAdsAndroidAppId\s*:\s*admobAndroidAppId \?: debugAdmobAndroidAppId/);
  assert.match(androidManifest, /com\.google\.android\.gms\.ads\.APPLICATION_ID/);
  assert.match(androidManifest, /\$\{freedGoogleMobileAdsAndroidAppId\}/);
  assert.match(androidManifest, /tools:replace="android:value"/);

  const resolved = execFileSync(
    process.execPath,
    [
      "-e",
      [
        "const { getConfig } = require('@expo/config');",
        "const { exp } = getConfig(process.cwd(), { skipSDKVersionRequirement: true, isPublicConfig: true });",
        "if (exp['react-native-google-mobile-ads']) process.exit(2);",
        "console.log(JSON.stringify({ plugins: exp.plugins }));"
      ].join("")
    ],
    {
      cwd: process.cwd(),
      encoding: "utf8",
      env: { PATH: process.env.PATH ?? "" },
      stdio: ["ignore", "pipe", "pipe"],
      timeout: CORE_TEST_CHILD_TIMEOUT_MS
    }
  );
  assert.doesNotMatch(resolved, /react-native-google-mobile-ads/);
});

