test("iOS debug build has a test AdMob application id while release remains env-driven", () => {
  const infoPlist = readFileSync("ios/FREED/Info.plist", "utf8");
  const project = readFileSync("ios/FREED.xcodeproj/project.pbxproj", "utf8");

  assert.match(infoPlist, /<key>GADApplicationIdentifier<\/key>\s*<string>\$\(GAD_APPLICATION_IDENTIFIER\)<\/string>/);
  assert.match(project, /GAD_APPLICATION_IDENTIFIER = "ca-app-pub-3940256099942544~1458002511";/);
  assert.match(project, /GAD_APPLICATION_IDENTIFIER = "\$\(EXPO_PUBLIC_ADMOB_APP_ID_IOS\)";/);
});

test("native monetization readiness reports missing production dependencies", () => {
  const previous = {
    mode: process.env.EXPO_PUBLIC_MONETIZATION_MODE,
    storeProvider: process.env.EXPO_PUBLIC_STORE_PROVIDER,
    revenueCatIos: process.env.EXPO_PUBLIC_REVENUECAT_API_KEY_IOS,
    purchaseVerifyEndpoint: process.env.EXPO_PUBLIC_PURCHASE_VERIFY_ENDPOINT,
    admobIos: process.env.EXPO_PUBLIC_ADMOB_APP_ID_IOS,
    rewardedIos: process.env.EXPO_PUBLIC_ADMOB_REWARDED_RESET_UNIT_ID_IOS,
    testAds: process.env.EXPO_PUBLIC_ADMOB_USE_TEST_ADS
  };

  try {
    process.env.EXPO_PUBLIC_MONETIZATION_MODE = "native";
    // This test exercises the legacy RevenueCat path. Native-IAP path is
    // tested separately below.
    process.env.EXPO_PUBLIC_STORE_PROVIDER = "revenuecat";
    delete process.env.EXPO_PUBLIC_REVENUECAT_API_KEY_IOS;
    delete process.env.EXPO_PUBLIC_ADMOB_APP_ID_IOS;
    delete process.env.EXPO_PUBLIC_ADMOB_REWARDED_RESET_UNIT_ID_IOS;
    process.env.EXPO_PUBLIC_ADMOB_USE_TEST_ADS = "false";
    configureNativeMonetizationProvider(null);

    const missing = getMonetizationReadiness({ platform: "ios" });
    assert.equal(missing.status, "missing-provider");
    assert.ok(missing.missing.includes("native monetization provider"));
    assert.ok(missing.missing.includes("RevenueCat API key"));
    assert.ok(missing.missing.includes("purchase verify endpoint"));
    assert.ok(missing.missing.includes("rewarded reset ad unit"));
    assert.ok(missing.missing.includes("AdMob app ID"));

    process.env.EXPO_PUBLIC_REVENUECAT_API_KEY_IOS = "appl_live1234567890";
    process.env.EXPO_PUBLIC_PURCHASE_VERIFY_ENDPOINT = "https://api.freedrecovery.app/api/purchases/verify";
    process.env.EXPO_PUBLIC_ADMOB_APP_ID_IOS = "ca-app-pub-1234567890123456~1234567890";
    process.env.EXPO_PUBLIC_ADMOB_REWARDED_RESET_UNIT_ID_IOS = "ca-app-pub-1234567890123456/1234567890";
    configureNativeMonetizationProvider({
      purchasePremiumPlan: async (plan) => ({
        status: "purchased",
        premium: true,
        provider: "native",
        message: `${plan.productId} purchased.`,
        planId: plan.id
      }),
      restorePremiumPurchases: async (plans) => ({
        status: "purchased",
        premium: true,
        provider: "native",
        message: "Restored.",
        planId: plans[0].id
      }),
      createRewardedResetSession: (config) => ({
        id: "ready-rewarded",
        provider: "native",
        status: "ready",
        durationSeconds: 1,
        placementId: config.rewardedResetPlacementId ?? undefined,
        message: "Ready."
      }),
      completeRewardedResetSession: async () => ({
        status: "completed",
        rewardGranted: true,
        provider: "native",
        message: "Rewarded."
      })
    });

    const ready = getMonetizationReadiness({ platform: "ios" });
    assert.equal(ready.status, "ready");
    assert.deepEqual(ready.missing, []);
    assert.equal(ready.revenueCatApiKeyConfigured, true);
    assert.equal(ready.admobAppIdConfigured, true);

    process.env.EXPO_PUBLIC_ADMOB_USE_TEST_ADS = "true";
    const testAdMode = getMonetizationReadiness({ platform: "ios" });
    assert.equal(testAdMode.status, "missing-config");
    assert.ok(testAdMode.missing.includes("disable AdMob test ads for production"));
    assert.equal(testAdMode.rewardedResetPlacementId, "google-mobile-ads-test-rewarded");
    assert.equal(testAdMode.allowTestAds, true);

    process.env.EXPO_PUBLIC_ADMOB_USE_TEST_ADS = "false";
    process.env.EXPO_PUBLIC_REVENUECAT_API_KEY_IOS = "test-key";
    process.env.EXPO_PUBLIC_ADMOB_APP_ID_IOS = "ca-app-pub-3940256099942544~1458002511";
    process.env.EXPO_PUBLIC_ADMOB_REWARDED_RESET_UNIT_ID_IOS = "ca-app-pub-3940256099942544/1712485313";
    const placeholderConfig = getMonetizationReadiness({ platform: "ios" });
    assert.equal(placeholderConfig.status, "missing-config");
    assert.ok(placeholderConfig.missing.includes("non-placeholder RevenueCat API key"));
    assert.ok(placeholderConfig.missing.includes("valid AdMob app ID"));
    assert.ok(placeholderConfig.missing.includes("valid rewarded reset ad unit"));
    assert.equal(placeholderConfig.revenueCatApiKeyConfigured, false);
    assert.equal(placeholderConfig.admobAppIdConfigured, false);
  } finally {
    restoreEnv("EXPO_PUBLIC_MONETIZATION_MODE", previous.mode);
    restoreEnv("EXPO_PUBLIC_STORE_PROVIDER", previous.storeProvider);
    restoreEnv("EXPO_PUBLIC_REVENUECAT_API_KEY_IOS", previous.revenueCatIos);
    restoreEnv("EXPO_PUBLIC_PURCHASE_VERIFY_ENDPOINT", previous.purchaseVerifyEndpoint);
    restoreEnv("EXPO_PUBLIC_ADMOB_APP_ID_IOS", previous.admobIos);
    restoreEnv("EXPO_PUBLIC_ADMOB_REWARDED_RESET_UNIT_ID_IOS", previous.rewardedIos);
    restoreEnv("EXPO_PUBLIC_ADMOB_USE_TEST_ADS", previous.testAds);
    configureNativeMonetizationProvider(null);
  }
});

test("native IAP (expo-iap) readiness does not require a RevenueCat API key", () => {
  const previous = {
    mode: process.env.EXPO_PUBLIC_MONETIZATION_MODE,
    storeProvider: process.env.EXPO_PUBLIC_STORE_PROVIDER,
    revenueCatIos: process.env.EXPO_PUBLIC_REVENUECAT_API_KEY_IOS,
    purchaseVerifyEndpoint: process.env.EXPO_PUBLIC_PURCHASE_VERIFY_ENDPOINT,
    admobIos: process.env.EXPO_PUBLIC_ADMOB_APP_ID_IOS,
    rewardedIos: process.env.EXPO_PUBLIC_ADMOB_REWARDED_RESET_UNIT_ID_IOS,
    testAds: process.env.EXPO_PUBLIC_ADMOB_USE_TEST_ADS
  };

  try {
    process.env.EXPO_PUBLIC_MONETIZATION_MODE = "native";
    process.env.EXPO_PUBLIC_STORE_PROVIDER = "native-iap";
    delete process.env.EXPO_PUBLIC_REVENUECAT_API_KEY_IOS;
    delete process.env.EXPO_PUBLIC_PURCHASE_VERIFY_ENDPOINT;
    process.env.EXPO_PUBLIC_ADMOB_APP_ID_IOS = "ca-app-pub-1234567890123456~1234567890";
    process.env.EXPO_PUBLIC_ADMOB_REWARDED_RESET_UNIT_ID_IOS = "ca-app-pub-1234567890123456/1234567890";
    process.env.EXPO_PUBLIC_ADMOB_USE_TEST_ADS = "false";

    configureNativeMonetizationProvider({
      purchasePremiumPlan: async (plan) => ({
        status: "purchased",
        premium: true,
        provider: "native",
        message: `${plan.productId} purchased via StoreKit 2.`,
        planId: plan.id
      }),
      restorePremiumPurchases: async (plans) => ({
        status: "purchased",
        premium: true,
        provider: "native",
        message: "Restored via StoreKit 2 / Play Billing.",
        planId: plans[0].id
      }),
      createRewardedResetSession: () => ({
        id: "iap-rewarded",
        provider: "native",
        status: "ready",
        durationSeconds: 1,
        message: "Ready."
      }),
      completeRewardedResetSession: async () => ({
        status: "completed",
        rewardGranted: true,
        provider: "native",
        message: "Rewarded."
      })
    });

    const missingEndpoint = getMonetizationReadiness({ platform: "ios" });
    assert.equal(missingEndpoint.status, "missing-config");
    assert.ok(missingEndpoint.missing.includes("purchase verify endpoint"));

    process.env.EXPO_PUBLIC_PURCHASE_VERIFY_ENDPOINT = "https://your-deployed-origin.example/iap/verify";
    const placeholderEndpoint = getMonetizationReadiness({ platform: "ios" });
    assert.equal(placeholderEndpoint.status, "missing-config");
    assert.ok(placeholderEndpoint.missing.includes("production-safe purchase verify endpoint"));
    assert.equal(placeholderEndpoint.purchaseVerifyEndpointConfigured, false);

    process.env.EXPO_PUBLIC_PURCHASE_VERIFY_ENDPOINT = "https://api.freedapp.com/iap/verify";
    const ready = getMonetizationReadiness({ platform: "ios" });
    assert.equal(ready.status, "ready");
    assert.deepEqual(ready.missing, []);
    // No RevenueCat key required when storeProvider is native-iap.
    assert.equal(ready.revenueCatApiKeyConfigured, false);
    assert.equal(ready.purchaseVerifyEndpointConfigured, true);
  } finally {
    restoreEnv("EXPO_PUBLIC_MONETIZATION_MODE", previous.mode);
    restoreEnv("EXPO_PUBLIC_STORE_PROVIDER", previous.storeProvider);
    restoreEnv("EXPO_PUBLIC_REVENUECAT_API_KEY_IOS", previous.revenueCatIos);
    restoreEnv("EXPO_PUBLIC_PURCHASE_VERIFY_ENDPOINT", previous.purchaseVerifyEndpoint);
    restoreEnv("EXPO_PUBLIC_ADMOB_APP_ID_IOS", previous.admobIos);
    restoreEnv("EXPO_PUBLIC_ADMOB_REWARDED_RESET_UNIT_ID_IOS", previous.rewardedIos);
    restoreEnv("EXPO_PUBLIC_ADMOB_USE_TEST_ADS", previous.testAds);
    configureNativeMonetizationProvider(null);
  }
});

