test("release verifier self-test exercises report artifact validation", () => {
  const result = runReleaseVerify(["--self-test"], {
    FREED_RELEASE_ENV_FILE: "https://secrets.freedrecovery.app/prod.env"
  });
  assert.equal(result.status, 0);
  assert.match(result.output, /release-verify self-test: pass/);
  assert.doesNotMatch(result.output, /release env file must be a local path/);
});

test("release verifier rejects unsafe env-file paths before running gates", () => {
  for (const args of [
    ["--list", "--env-file", "https://secrets.freedrecovery.app/prod.env"],
    ["--env-file", "--verbose"],
    ["--list", "--env-file", "<production-env-file>"],
    ["--list", "--env-file", ".env.example"]
  ]) {
    const result = runReleaseVerify(args);
    assert.notEqual(result.status, 0, args.join(" "));
    assert.match(result.output, /release env file must be a local path without shell syntax, URLs, flags, or template placeholders/);
    assert.doesNotMatch(result.output, /Env file not found/);
    assert.doesNotMatch(result.output, /FREED release verification command order/);
  }
});

test("release verifier rejects validation env-file folders before running gates", () => {
  for (const args of [
    ["--list", "--env-file", "docs/validation/evidence/prod.env"],
    ["--list", "--env-file", "DOCS/VALIDATION/EVIDENCE/prod.env"],
    ["--list", "--env-file", "docs/validation/artifacts/release-run/prod.env"]
  ]) {
    const result = runReleaseVerify(args);
    assert.notEqual(result.status, 0, args.join(" "));
    assert.match(result.output, /release env file must not be stored in docs\/validation\/(evidence|artifacts)/);
    assert.doesNotMatch(result.output, /Env file not found/);
    assert.doesNotMatch(result.output, /FREED release verification command order/);
  }
});

test("release verifier rejects unsafe env-file environment values", () => {
  const result = runReleaseVerify(["--list"], {
    FREED_RELEASE_ENV_FILE: "https://secrets.freedrecovery.app/prod.env"
  });
  assert.notEqual(result.status, 0);
  assert.match(result.output, /release env file must be a local path without shell syntax, URLs, flags, or template placeholders/);
  assert.doesNotMatch(result.output, /FREED release verification command order/);
});

test("release verifier rejects malformed env-file lines before listing gates", () => {
  const root = mkdtempSync(join(tmpdir(), "freed-release-verify-env-"));
  const envFile = join(root, ".env.production");
  try {
    writeFileSync(envFile, ["GOOD=value", "# spacer", "", "MISSING_EQUALS"].join("\n"));
    const result = runReleaseVerify(["--list", "--env-file", envFile]);
    assert.notEqual(result.status, 0);
    assert.match(result.output, /release env file line 4 must use KEY=value syntax/);
    assert.doesNotMatch(result.output, /FREED release verification command order/);
  } finally {
    rmSync(root, { recursive: true, force: true });
  }
});

test("release verifier rejects duplicate env-file keys before listing gates", () => {
  const root = mkdtempSync(join(tmpdir(), "freed-release-verify-env-"));
  const envFile = join(root, ".env.production");
  try {
    writeFileSync(envFile, ["GOOD=value", "# spacer", "", "GOOD=again"].join("\n"));
    const result = runReleaseVerify(["--list", "--env-file", envFile]);
    assert.notEqual(result.status, 0);
    assert.match(result.output, /release env file line 4 repeats GOOD from line 1/);
    assert.doesNotMatch(result.output, /FREED release verification command order/);
  } finally {
    rmSync(root, { recursive: true, force: true });
  }
});

test("release verifier rejects missing or unknown release arguments", () => {
  for (const args of [["--env-file"], ["--env-file="], ["--artifact-dir"], ["--artifact-dir="], ["--unknown"]]) {
    const result = runReleaseVerify(args);
    assert.notEqual(result.status, 0, args.join(" "));
    assert.match(result.output, /Missing value for|Unknown option:/);
    assert.doesNotMatch(result.output, /FREED release verification command order/);
  }

  for (const args of [
    ["--list", "--artifact-dir", "https://qa.freedrecovery.app/reports"],
    ["--list", "--artifact-dir", "../release-reports"],
    ["--list", "--artifact-dir", "screenshots/release-reports"],
    ["--list", "--artifact-dir", "docs/validation/evidence"],
    ["--list", "--artifact-dir", "docs/validation/artifacts"],
    ["--list", "--artifact-dir", "<run-id>"],
    ["--list", "--artifact-dir", "docs/validation/artifacts/run;rm"]
  ]) {
    const result = runReleaseVerify(args);
    assert.notEqual(result.status, 0, args.join(" "));
    assert.match(result.output, /release artifact directory must/);
    assert.doesNotMatch(result.output, /FREED release verification command order/);
  }
});

