test("release readiness audit reports sanitized dependency audit command failures", () => {
  const fakeBinDir = mkdtempSync(join(tmpdir(), "freed-fake-npm-"));
  const fakeNpmPath = join(fakeBinDir, "npm");

  try {
    writeFileSync(
      fakeNpmPath,
      [
        "#!/usr/bin/env node",
        "if (process.argv.includes('audit')) {",
        "  console.error('npm ERR! audit registry unavailable https://registry.npmjs.org/audit?token=secret-value');",
        "  console.error('npm ERR! bearer eyJhbGciOiJFUzI1NiJ9.eyJpc3MiOiIxMjM0NTY3OCIsInN1YiI6InNlcnZpY2UifQ.signaturesegment');",
        "  process.exit(1);",
        "}",
        "console.error('unexpected npm command');",
        "process.exit(1);"
      ].join("\n")
    );
    chmodSync(fakeNpmPath, 0o755);

    const output = runReleaseReadinessAudit({
      FREED_DEPENDENCY_AUDIT_REPORT: "none",
      PATH: `${fakeBinDir}:${dirname(process.execPath)}:${process.env.PATH ?? ""}`
    });

    assert.match(output, /dependency-security/);
    assert.match(output, /Production dependency audit did not return a parseable vulnerability report after exit code 1/);
    assert.match(output, /npm ERR! audit registry unavailable \[redacted-url\]/);
    assert.doesNotMatch(output, /secret-value/);
    assert.doesNotMatch(output, /eyJhbGciOiJFUzI1NiJ9/);
    assert.match(output, /\[redacted-secret\]/);
  } finally {
    rmSync(fakeBinDir, { recursive: true, force: true });
  }
});

test("release readiness audit writes sanitized JSON reports", () => {
  const dir = mkdtempSync(join(process.cwd(), "docs/validation/artifacts/core-release-readiness-"));
  const reportPath = join(dir, "release-readiness-report.json");
  try {
    const output = runReleaseReadinessAudit({}, ["--report", reportPath]);
    const report = JSON.parse(readFileSync(reportPath, "utf8"));

    assert.match(output, /# FREED release readiness audit/);
    assert.equal(report.schemaVersion, "release-readiness-report-v1");
    assert.equal(typeof report.generatedAt, "string");
    assert.equal(report.sanitized, true);
    assert.equal(report.strict, false);
    assert.ok(Array.isArray(report.results));
    assert.equal(
      report.summary.passCount,
      report.results.filter((entry: { status?: string }) => entry.status === "pass").length
    );
    assert.equal(
      report.summary.failCount,
      report.results.filter((entry: { status?: string }) => entry.status === "fail").length
    );
    assert.equal(
      report.summary.warnCount,
      report.results.filter((entry: { status?: string }) => entry.status === "warn").length
    );
    assert.ok(report.summary.passCount > 0);
    assert.ok(report.summary.failCount > 0);
    assert.ok(report.results.some((entry: { id?: string; status?: string }) => entry.id === "store-legal-hosted-url-validation" && entry.status === "fail"));
    assert.ok(report.results.some((entry: { id?: string; status?: string }) => entry.id === "production-backend-infrastructure" && entry.status === "fail"));
    assert.ok(report.results.some((entry: { id?: string; status?: string }) => entry.id === "android-native-safety-contract" && entry.status === "pass"));
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
});

test("release readiness report redacts unsafe URL and secret-shaped evidence text", () => {
  const dir = mkdtempSync(join(process.cwd(), "docs/validation/artifacts/core-release-redaction-"));
  const reportPath = join(dir, "release-readiness-report.json");
  try {
    runReleaseReadinessAudit(
      {
        EXPO_PUBLIC_AI_COACH_ENDPOINT: "https://user:pass@private.example.com/api/clara?token=secret",
        EXPO_PUBLIC_AI_CHALLENGE_ENDPOINT: "https://private.example.com/api/challenges?access_token=abc123",
        OPENAI_API_KEY: "sk-proj-1234567890abcdefghijklmnopqrstuvwxyz"
      },
      ["--report", reportPath]
    );
    const reportText = readFileSync(reportPath, "utf8");

    assert.doesNotMatch(reportText, /private\.example\.com/);
    assert.doesNotMatch(reportText, /token=secret|access_token=abc123/);
    assert.doesNotMatch(reportText, /sk-proj-1234567890abcdefghijklmnopqrstuvwxyz/);
    assert.match(reportText, /\[redacted-url\]|\[redacted-secret\]|production-ai-backend/);
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
});

test("release readiness audit rejects unsafe report paths and unknown args", () => {
  for (const args of [
    ["--report", "https://qa.freedrecovery.app/release-readiness.json"],
    ["--report", "../release-readiness.json"],
    ["--report", "screenshots/release-readiness.json"],
    ["--report", "docs/validation/evidence/release-readiness.json"],
    ["--report", "DOCS/VALIDATION/EVIDENCE/release-readiness.json"],
    ["--report", "docs/validation/artifacts/release-readiness.json"],
    ["--report", "docs/validation/artifacts/run/release-readiness.txt"],
    ["--report", "<run-id>/release-readiness.json"],
    ["--report"],
    ["--unknown"]
  ]) {
    const result = runReleaseReadinessAuditWithArgs(args);
    assert.notEqual(result.status, 0, args.join(" "));
    assert.match(result.output, /--report must|Missing value for --report|Unknown option/);
    assert.doesNotMatch(result.output, /# FREED release readiness audit/);
  }
});

