test("typescript entry runner rejects unsafe env-file paths", () => {
  for (const value of [
    "https://secrets.freedrecovery.app/prod.env",
    "--verbose",
    "<production-env-file>",
    ".env.production.example",
    "secrets/prod.env|printenv"
  ]) {
    const result = runTsEntrypointWithEnvFilePath("scripts/ai-backend-smoke.ts", value);
    assert.notEqual(result.status, 0, value);
    assert.match(result.output, /release env file must be a local path without shell syntax, URLs, flags, or template placeholders/);
    assert.doesNotMatch(result.output, /Endpoint is not configured/);
  }
});

test("typescript entry runner rejects validation env-file folders", () => {
  for (const value of [
    "docs/validation/evidence/prod.env",
    "DOCS/VALIDATION/EVIDENCE/prod.env",
    "docs/validation/artifacts/release-run/prod.env"
  ]) {
    const result = runTsEntrypointWithEnvFilePath("scripts/ai-backend-smoke.ts", value);
    assert.notEqual(result.status, 0, value);
    assert.match(result.output, /release env file must not be stored in docs\/validation\/(evidence|artifacts)/);
    assert.doesNotMatch(result.output, /Endpoint is not configured/);
  }
});

