test("store and AI evidence helpers load non-secret release env context", () => {
  const root = mkdtempSync(join(tmpdir(), "freed-helper-env-"));
  const envFile = join(root, ".env.production");
  const secretAppleKey = "-----BEGIN PRIVATE KEY-----\\nSHOULD_NOT_APPEAR\\n-----END PRIVATE KEY-----";
  const secretGeminiKey = "AIzaSyShouldNotAppearInCaptureArtifacts123456";
  writeFileSync(
    envFile,
    [
      "EXPO_PUBLIC_STORE_PROVIDER=revenuecat",
      "FREED_IOS_PRODUCT_ID=freed_ios_yearly",
      "FREED_ANDROID_PRODUCT_ID=freed_android_yearly",
      "EXPO_PUBLIC_PREMIUM_ENTITLEMENT_ID=freed-premium",
      "EXPO_PUBLIC_PURCHASE_VERIFY_ENDPOINT=https://api.freedrecovery.app/api/purchases/verify",
      "EXPO_PUBLIC_ADMOB_REWARDED_RESET_UNIT_ID_IOS=ca-app-pub-1234567890123456/1234567890",
      "EXPO_PUBLIC_ADMOB_REQUEST_COUNTRY=US",
      "EXPO_PUBLIC_AI_COACH_ENDPOINT=https://api.freedrecovery.app/api/clara",
      "EXPO_PUBLIC_AI_CHALLENGE_ENDPOINT=https://api.freedrecovery.app/api/challenges",
      "EXPO_PUBLIC_RETENTION_ENDPOINT=https://api.freedrecovery.app/api/retention",
      "GEMINI_MODEL=gemini-2.5-flash",
      `APP_STORE_PRIVATE_KEY=${secretAppleKey}`,
      `GEMINI_API_KEY=${secretGeminiKey}`
    ].join("\n")
  );

  try {
    const store = runStoreAdEvidenceArgs([
      "--release-env-file",
      envFile,
      "--ios-product-id",
      "freed_cli_ios_yearly",
      "--run-id",
      "env-file-store-capture",
      "--plan-only"
    ]);
    assert.equal(store.status, 0, store.output);
    const storePayload = JSON.parse(store.output);
    assert.equal(storePayload.releaseEnvFileLoaded, true);
    assert.equal(storePayload.configured.storeProvider, "revenuecat");
    assert.equal(storePayload.configured.iosProductId, "freed_cli_ios_yearly");
    assert.equal(storePayload.configured.androidProductId, "freed_android_yearly");
    assert.equal(storePayload.configured.entitlementId, "freed-premium");
    assert.equal(storePayload.configured.purchaseVerifyEndpoint, "https://api.freedrecovery.app/api/purchases/verify");
    assert.equal(storePayload.configured.rewardedAdUnitId, "ca-app-pub-1234567890123456/1234567890");
    assert.equal(storePayload.configured.adRequestCountryCode, "US");
    assert.match(storePayload.commandHandoff.releasePreflightCommand, /--env-file/);
    assert.match(JSON.stringify(storePayload.matrixRows), /purchase-verification-smoke-report\.json/);
    assert.match(JSON.stringify(storePayload.matrixRows), /sanctioned command shape/);
    assert.doesNotMatch(store.output, /SHOULD_NOT_APPEAR/);
    assert.doesNotMatch(store.output, new RegExp(secretGeminiKey));

    const ai = runAiBackendEvidenceArgs([
      "--release-env-file",
      envFile,
      "--challenge-endpoint",
      "https://ai.freedrecovery.app/api/challenges",
      "--run-id",
      "env-file-ai-capture",
      "--plan-only"
    ]);
    assert.equal(ai.status, 0, ai.output);
    const aiPayload = JSON.parse(ai.output);
    assert.equal(aiPayload.releaseEnvFileLoaded, true);
    assert.equal(aiPayload.configured.coachEndpoint, "https://api.freedrecovery.app/api/clara");
    assert.equal(aiPayload.configured.challengeEndpoint, "https://ai.freedrecovery.app/api/challenges");
    assert.equal(aiPayload.configured.retentionEndpoint, "https://api.freedrecovery.app/api/retention");
    assert.equal(aiPayload.configured.model, "gemini-2.5-flash");
    assert.match(aiPayload.commandHandoff.smokeCommand, /--env-file/);
    assert.match(JSON.stringify(aiPayload.matrixRows), /ai-backend-smoke-report\.json/);
    assert.match(JSON.stringify(aiPayload.matrixRows), /retentionAggregateOnlyVerified/);
    assert.match(JSON.stringify(aiPayload.matrixRows), /sanctioned command shape/);
    assert.doesNotMatch(ai.output, /SHOULD_NOT_APPEAR/);
    assert.doesNotMatch(ai.output, new RegExp(secretGeminiKey));

    const missingStoreEnv = runStoreAdEvidenceArgs(["--release-env-file", join(root, "missing.env"), "--plan-only"]);
    assert.notEqual(missingStoreEnv.status, 0);
    assert.match(missingStoreEnv.output, /Env file not found/);

    const wrongStorePath = runStoreAdEvidenceArgs([
      "--purchase-verify-endpoint",
      "https://api.freedrecovery.app/api/store/verify",
      "--plan-only"
    ]);
    assert.notEqual(wrongStorePath.status, 0);
    assert.match(wrongStorePath.output, /\/api\/purchases\/verify/);

    const malformedRewardedUnit = runStoreAdEvidenceArgs([
      "--rewarded-ad-unit-id",
      "google-mobile-ads-test-rewarded",
      "--plan-only"
    ]);
    assert.notEqual(malformedRewardedUnit.status, 0);
    assert.match(malformedRewardedUnit.output, /production-format AdMob rewarded unit id/);
    assert.doesNotMatch(malformedRewardedUnit.output, /pending-manual-qa/);

    const sampleRewardedUnit = runStoreAdEvidenceArgs([
      "--rewarded-ad-unit-id",
      "ca-app-pub-3940256099942544/1712485313",
      "--plan-only"
    ]);
    assert.notEqual(sampleRewardedUnit.status, 0);
    assert.match(sampleRewardedUnit.output, /Google sample publisher id/);
    assert.doesNotMatch(sampleRewardedUnit.output, /pending-manual-qa/);

    const wrongAiPath = runAiBackendEvidenceArgs([
      "--coach-endpoint",
      "https://api.freedrecovery.app/api/coach",
      "--challenge-endpoint",
      "https://api.freedrecovery.app/api/challenges",
      "--plan-only"
    ]);
    assert.notEqual(wrongAiPath.status, 0);
    assert.match(wrongAiPath.output, /\/api\/clara/);
  } finally {
    rmSync(root, { recursive: true, force: true });
  }
});

test("physical-device evidence helpers write plan-only capture packets", () => {
  const runId = `physical-plan-${Date.now()}`;
  const artifactRoot = join(process.cwd(), "docs/validation/artifacts", runId);
  const iosOutputDir = `docs/validation/artifacts/${runId}/ios-physical-device-capture`;
  const androidOutputDir = `docs/validation/artifacts/${runId}/android-real-browser-capture`;

  try {
    const ios = runIosPhysicalEvidenceArgs([
      "--plan-only",
      "--adult-host",
      "adult-domain.realsite.com",
      "--run-id",
      runId,
      "--output-dir",
      iosOutputDir
    ]);
    assert.equal(ios.status, 0, ios.output);
    const iosPayload = JSON.parse(ios.output);
    assert.equal(iosPayload.schema, "freed-ios-physical-device-capture-v1");
    assert.equal(iosPayload.result, "plan-only");
    assert.equal(iosPayload.sanitized, true);
    assert.equal(iosPayload.evidenceSatisfied, false);
    assert.match(iosPayload.manifestArtifact, /capture-manifest\.json/);
    assert.match(iosPayload.evidenceFillTemplateArtifact, /ios-physical-device-evidence-fill-template\.json/);
    assert.equal(existsSync(join(process.cwd(), iosPayload.manifestArtifact)), true);
    assert.equal(existsSync(join(process.cwd(), iosPayload.evidenceFillTemplateArtifact)), true);
    const iosManifest = JSON.parse(readFileSync(join(process.cwd(), iosPayload.manifestArtifact), "utf8"));
    assert.equal(iosManifest.manualVerificationRequired, true);
    assert.equal(iosManifest.releaseGate, "ios-physical-device-validation");

    const android = runAndroidRealBrowserEvidenceArgs([
      "--plan-only",
      "--adult-url",
      "https://adult-domain.realsite.com/path",
      "--run-id",
      runId,
      "--output-dir",
      androidOutputDir
    ]);
    assert.equal(android.status, 0, android.output);
    const androidPayload = JSON.parse(android.output);
    assert.equal(androidPayload.schema, "freed-android-real-browser-capture-v1");
    assert.equal(androidPayload.result, "plan-only");
    assert.equal(androidPayload.sanitized, true);
    assert.equal(androidPayload.evidenceSatisfied, false);
    assert.match(androidPayload.manifestArtifact, /capture-manifest\.json/);
    assert.match(androidPayload.evidenceFillTemplateArtifact, /android-real-browser-evidence-fill-template\.json/);
    assert.equal(existsSync(join(process.cwd(), androidPayload.manifestArtifact)), true);
    assert.equal(existsSync(join(process.cwd(), androidPayload.evidenceFillTemplateArtifact)), true);
    const androidManifest = JSON.parse(readFileSync(join(process.cwd(), androidPayload.manifestArtifact), "utf8"));
    assert.equal(androidManifest.manualVerificationRequired, true);
    assert.equal(androidManifest.releaseGate, "android-real-browser-validation");
  } finally {
    rmSync(artifactRoot, { recursive: true, force: true });
  }
});

test("store and AI evidence helpers reject malformed release env files before capture", () => {
  const root = mkdtempSync(join(tmpdir(), "freed-helper-env-bad-"));
  const malformedEnvFile = join(root, "malformed.env");
  const duplicateEnvFile = join(root, "duplicate.env");
  writeFileSync(malformedEnvFile, ["GOOD=value", "# spacer", "", "MISSING_EQUALS"].join("\n"));
  writeFileSync(duplicateEnvFile, ["GOOD=value", "# spacer", "", "GOOD=again"].join("\n"));

  try {
    for (const [label, runner] of [
      ["store", runStoreAdEvidenceArgs],
      ["ai", runAiBackendEvidenceArgs]
    ] as const) {
      const malformed = runner(["--release-env-file", malformedEnvFile, "--plan-only"]);
      assert.notEqual(malformed.status, 0, label);
      assert.match(malformed.output, /--release-env-file line 4 must use KEY=value syntax/);
      assert.doesNotMatch(malformed.output, /pending-manual-qa/);

      const duplicate = runner(["--release-env-file", duplicateEnvFile, "--plan-only"]);
      assert.notEqual(duplicate.status, 0, label);
      assert.match(duplicate.output, /--release-env-file line 4 repeats GOOD from line 1/);
      assert.doesNotMatch(duplicate.output, /pending-manual-qa/);
    }
  } finally {
    rmSync(root, { recursive: true, force: true });
  }
});

