    assert.match(runIdFailing?.evidence ?? "", /ai\.challengePersonalizationRunId/);
    assert.match(runIdFailing?.evidence ?? "", /ai\.noCoordinateFieldsRunId/);
    assert.match(runIdFailing?.evidence ?? "", /ai\.noSensitiveEchoRunId/);
