  await asyncTest("server JSON body reader fails closed for non-JSON and oversized payloads", async () => {
    const nonJson = await readBoundedJsonBody(
      new Request("http://localhost/api/test", {
        method: "POST",
        headers: { "Content-Type": "text/plain" },
        body: "private.example.com token=secret"
      }),
      { maxBytes: 32, routeLabel: "Test route" }
    );
    const oversizedByHeader = await readBoundedJsonBody(
      new Request("http://localhost/api/test", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          "Content-Length": "33"
        },
        body: JSON.stringify({ ok: true })
      }),
      { maxBytes: 32, routeLabel: "Test route" }
    );
    const oversizedByBody = await readBoundedJsonBody(
      new Request("http://localhost/api/test", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ padding: "x".repeat(64), secret: "raw-secret" })
      }),
      { maxBytes: 32, routeLabel: "Test route" }
    );
    const malformed = await readBoundedJsonBody(
      new Request("http://localhost/api/test", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: "{\"private\":\"unterminated"
      }),
      { maxBytes: 1024, routeLabel: "Test route" }
    );

    assert.equal(nonJson.ok, false);
    assert.equal(nonJson.status, 415);
    assert.equal(JSON.stringify(nonJson).includes("private.example.com"), false);
    assert.equal(JSON.stringify(nonJson).includes("token=secret"), false);
    assert.equal(oversizedByHeader.ok, false);
    assert.equal(oversizedByHeader.status, 413);
    assert.equal(oversizedByBody.ok, false);
    assert.equal(oversizedByBody.status, 413);
    assert.equal(JSON.stringify(oversizedByBody).includes("raw-secret"), false);
    assert.equal(malformed.ok, false);
    assert.equal(malformed.status, 400);
    assert.equal(JSON.stringify(malformed).includes("unterminated"), false);
  });

  await asyncTest("provider JSON response reader fails closed for oversized payloads", async () => {
    const small = await readBoundedResponseJson(
      new Response(JSON.stringify({ ok: true }), {
        headers: { "Content-Type": "application/json" }
      }),
      { timeoutMs: 500, maxBytes: 64, label: "Provider response" }
    );
    assert.deepEqual(small, { ok: true });

    let textCalled = false;
    let jsonCalled = false;
    const oversizedByHeader = {
      headers: new Headers({ "Content-Length": "65" }),
      text: async () => {
        textCalled = true;
        return "{}";
      },
      json: async () => {
        jsonCalled = true;
        return {};
      }
    };
    await assert.rejects(
      () => readBoundedResponseJson(oversizedByHeader, { timeoutMs: 500, maxBytes: 64, label: "Provider response" }),
      /Provider response exceeds 64 bytes/
    );
    assert.equal(textCalled, false);
    assert.equal(jsonCalled, false);

    await assert.rejects(
      () =>
        readBoundedResponseJson(
          new Response(JSON.stringify({ padding: "x".repeat(96) }), {
            headers: { "Content-Type": "application/json" }
          }),
          { timeoutMs: 500, maxBytes: 64, label: "Provider response" }
        ),
      /Provider response exceeds 64 bytes/
    );

    let unreadableAborted = false;
    await assert.rejects(
      () =>
        readBoundedResponseJson(
          {
            json: async () => ({ mock: true })
          },
          {
            timeoutMs: 500,
            maxBytes: 1,
            label: "Mock provider response",
            abort: () => {
              unreadableAborted = true;
            }
          }
        ),
      /Mock provider response cannot be size-checked/
    );
    assert.equal(unreadableAborted, true);
  });

  await asyncTest("backend job runner records sanitized job metadata with Redis lock", async () => {
    const records: BackendJobRunRecord[] = [];
    let unlocked = false;

    configureBackendRedisLockProvider(
      (input) => ({
        acquired: true,
        provider: "custom",
        status: "ok",
        key: input.key,
        token: input.token,
        ttlMs: input.ttlMs
      }),
      () => {
        unlocked = true;
      }
    );
    configureBackendJobRunProvider((record) => {
      records.push(record);
      return {
        recorded: true,
        provider: "custom",
        status: "ok",
        tableName: "backend_job_runs",
        jobName: record.jobName,
        idempotencyKey: record.idempotencyKey
      };
    });

    try {
      const outcome = await runBackendJob(
        {
          jobName: "adult-domain-feed-sync",
          idempotencyKey: "adult-feed-publication-test",
          lockKey: "freed:adult-domain-feed-sync:test",
          lockTtlMs: 30_000,
          metadata: {
            version: "feed-publication-test",
            checksum: "sha256-test",
            domainCount: 12,
            rawUrl: "https://private.example.com/raw-feed?token=secret",
            privateNotes: "do not store"
          }
        },
        async () => "published"
      );
      const metadataText = JSON.stringify(records.map((record) => record.metadata));

      assert.equal(outcome.result, "published");
      assert.equal(outcome.status, "succeeded");
      assert.equal(outcome.lock.status, "ok");
      assert.equal(unlocked, true);
      assert.equal(records.length, 2);
      assert.deepEqual(records.map((record) => record.status), ["started", "succeeded"]);
      assert.equal(records.every((record) => record.jobName === "adult-domain-feed-sync"), true);
      assert.equal(metadataText.includes("private.example.com"), false);
      assert.equal(metadataText.includes("token=secret"), false);
      assert.equal(metadataText.includes("privateNotes"), false);
      assert.equal(metadataText.includes("rawUrl"), false);
    } finally {
      configureBackendRedisLockProvider(null);
      configureBackendJobRunProvider(null);
    }
  });

