  await asyncTest("backend cleanup API requires maintenance secret and records job status", async () => {
    const previousSecret = process.env.BACKEND_MAINTENANCE_SECRET;
    const records: BackendJobRunRecord[] = [];
    const route = await import("../app/api/backend/cleanup+api");

    configureBackendRetentionCleanupProvider((cleanedAt, cutoff) => ({
      ok: true,
      provider: "custom",
      status: "ok",
      cleanedAt,
      cutoff,
      tables: [
        {
          target: "analytics",
          tableName: "recovery_analytics_events",
          status: "ok",
          deletedCount: 3
        }
      ]
    }));
    configureBackendJobRunProvider((record) => {
      records.push(record);
      return {
        recorded: true,
        provider: "custom",
        status: "ok",
        tableName: "backend_job_runs",
        jobName: record.jobName,
        idempotencyKey: record.idempotencyKey
      };
    });

    try {
      process.env.BACKEND_MAINTENANCE_SECRET = "backend-maintenance-secret-123";
      assert.equal(validateBackendMaintenanceAuth(
        new Request("http://localhost/api/backend/cleanup", {
          headers: { authorization: "Bearer test-maintenance-secret-1234567890" }
        }),
        { BACKEND_MAINTENANCE_SECRET: "test-maintenance-secret-1234567890" }
      ), false);
      assert.equal(validateBackendMaintenanceAuth(
        new Request("http://localhost/api/backend/cleanup", {
          headers: { authorization: "Bearer backend-maintenance-secret-123" }
        })
      ), true);

      const unauthorized = await route.POST(
        new Request("http://localhost/api/backend/cleanup", {
          method: "POST"
        })
      );
      const authorized = await route.POST(
        new Request("http://localhost/api/backend/cleanup", {
          method: "POST",
          headers: { authorization: "Bearer backend-maintenance-secret-123" }
        })
      );
      const unauthorizedPayload = await unauthorized.json();
      const authorizedPayload = await authorized.json();
      const metadataText = JSON.stringify(records.map((record) => record.metadata));

      assert.equal(unauthorized.status, 401);
      assert.equal(unauthorizedPayload.status, "unauthorized");
      assert.equal(authorized.status, 200);
      assert.equal(authorizedPayload.ok, true);
      assert.equal(authorizedPayload.cleanup.tables[0].deletedCount, 3);
      assert.equal(records.length, 2);
      assert.equal(records.every((record) => record.jobName === "analytics-retention-cleanup"), true);
      assert.equal(metadataText.includes("rawUrl"), false);
      assert.equal(metadataText.includes("privateNotes"), false);
      assert.equal(JSON.stringify(authorizedPayload).includes("backend-maintenance-secret-123"), false);
    } finally {
      restoreEnv("BACKEND_MAINTENANCE_SECRET", previousSecret);
      configureBackendRetentionCleanupProvider(null);
      configureBackendJobRunProvider(null);
    }
  });

  await asyncTest("adult domain feed sync resolves remote feeds and falls back safely", async () => {
    const conditionalRequests: RequestInit[] = [];
    let oversizedBodyRead = false;
    let unsafeEndpointFetchCount = 0;
    const freshGeneratedAt = new Date().toISOString();
    const remoteFeedPayload = {
      version: "remote-feed-2026-05-16",
      generatedAt: freshGeneratedAt,
      domains: ["0.0.0.0 adult-remote.example", "mail.google.com"],
      exceptions: ["google.com"],
      sources: [{ id: "freed-custom", label: "Remote feed", domainCount: 2 }]
    };
    const remote = await resolveAdultDomainFeed(
      async () => ({
        ok: true,
        status: 200,
        text: async () => JSON.stringify(remoteFeedPayload),
        json: async () => remoteFeedPayload
      }),
      "https://api.freedrecovery.app/api/adult-domain-feed"
    );
    const cached = await resolveAdultDomainFeed(
      async (_input, init) => {
        conditionalRequests.push(init ?? {});
        return {
          ok: false,
          status: 304,
          json: async () => {
            throw new Error("304 responses must not be parsed");
          }
        };
      },
      "https://api.freedrecovery.app/api/adult-domain-feed",
      "fnv1a32:1a2b3c4d"
    );
    const failed = await resolveAdultDomainFeed(
      async () => {
        throw new Error("network down");
      },
      "https://api.freedrecovery.app/api/adult-domain-feed"
    );
    const timedOut = await resolveAdultDomainFeed(
      async () =>
        new Promise(() => {
          // Simulates a stalled deployed feed endpoint; sync must not hang startup.
        }),
      "https://api.freedrecovery.app/api/adult-domain-feed",
      null,
      { timeoutMs: 50 }
    );
    const oversized = await resolveAdultDomainFeed(
      async () => ({
        ok: true,
        status: 200,
        headers: new Headers({ "Content-Length": "100001" }),
        text: async () => {
          oversizedBodyRead = true;
          return "{}";
        },
        json: async () => {
          oversizedBodyRead = true;
          return {};
        }
      }),
      "https://api.freedrecovery.app/api/adult-domain-feed",
      null,
      { maxBytes: 100_000 }
    );
    const stale = await resolveAdultDomainFeed(
      async () => ({
        ok: true,
        status: 200,
        text: async () => JSON.stringify({
          ...remoteFeedPayload,
          generatedAt: "2001-01-01T00:00:00.000Z",
          domains: ["adult-stale-sync.example"],
          exceptions: []
        }),
        json: async () => ({})
      }),
      "https://api.freedrecovery.app/api/adult-domain-feed"
    );
    const future = await resolveAdultDomainFeed(
      async () => ({
        ok: true,
        status: 200,
        text: async () => JSON.stringify({
          ...remoteFeedPayload,
          generatedAt: "2999-01-01T00:00:00.000Z",
          domains: ["adult-future-sync.example"],
          exceptions: []
        }),
        json: async () => ({})
      }),
      "https://api.freedrecovery.app/api/adult-domain-feed"
    );
    const unsafeEndpoint = await resolveAdultDomainFeed(
      async () => {
        unsafeEndpointFetchCount += 1;
        throw new Error("unsafe adult-domain feed endpoint should not be fetched");
      },
      "https://user:pass@api.freedrecovery.app/api/adult-domain-feed?token=secret#access_token=secret"
    );

    assert.equal(remote.provider, "remote");
    assert.equal(remote.warning, null);
    assert.deepEqual(remote.feed?.domains, ["adult-remote.example"]);
    assert.equal(cached.provider, "remote-cache");
    assert.equal(cached.feed, null);
    assert.equal(cached.notModified, true);
    assert.equal((conditionalRequests[0].headers as Record<string, string>)["If-None-Match"], '"fnv1a32:1a2b3c4d"');
    assert.equal((conditionalRequests[0].headers as Record<string, string>)["X-FREED-Adult-Feed-Checksum"], "fnv1a32:1a2b3c4d");
    assert.equal(failed.provider, "embedded");
    assert.match(failed.warning ?? "", /network down/);
    assert.equal(failed.feed?.domains.length, ADULT_DOMAIN_SEEDS.length);
    assert.equal(timedOut.provider, "embedded");
    assert.match(timedOut.warning ?? "", /timed out/);
    assert.equal(timedOut.feed?.domains.length, ADULT_DOMAIN_SEEDS.length);
    assert.equal(oversized.provider, "embedded");
    assert.match(oversized.warning ?? "", /response exceeds 100000 bytes/);
    assert.equal(oversizedBodyRead, false);
    assert.equal(oversized.feed?.domains.length, ADULT_DOMAIN_SEEDS.length);
    assert.equal(stale.provider, "embedded");
    assert.match(stale.warning ?? "", /older than 48 hours/);
    assert.equal(stale.feed?.domains.length, ADULT_DOMAIN_SEEDS.length);
    assert.equal(future.provider, "embedded");
    assert.match(future.warning ?? "", /must not be in the future/);
    assert.equal(future.feed?.domains.length, ADULT_DOMAIN_SEEDS.length);
    assert.equal(unsafeEndpoint.provider, "embedded");
    assert.match(unsafeEndpoint.warning ?? "", /endpoint is not production-safe/);
    assert.equal(unsafeEndpointFetchCount, 0);
    assert.equal(unsafeEndpoint.feed?.domains.length, ADULT_DOMAIN_SEEDS.length);
  });

