  await asyncTest("challenge weather context stays coarse and bounded", async () => {
    const requestedUrls: string[] = [];
    const config = getChallengeWeatherContextConfig({
      EXPO_PUBLIC_CHALLENGE_WEATHER_CONTEXT_ENABLED: "true",
      EXPO_PUBLIC_CHALLENGE_WEATHER_CONTEXT_ENDPOINT: "https://api.open-meteo.com/v1/forecast",
      EXPO_PUBLIC_CHALLENGE_WEATHER_CONTEXT_TIMEOUT_MS: "500",
      EXPO_PUBLIC_CHALLENGE_WEATHER_CONTEXT_RESPONSE_MAX_BYTES: "1024"
    });
    const weather = await fetchChallengeWeatherContext(
      { latitude: 37.7749, longitude: -122.4194 },
      (async (input) => {
        requestedUrls.push(String(input));
        return new Response(JSON.stringify({ current: { temperature_2m: 12.4, weather_code: 61 } }), {
          status: 200,
          headers: { "Content-Type": "application/json" }
        });
      }) as typeof fetch,
      config
    );
    const oversized = await fetchChallengeWeatherContext(
      { latitude: 37.7749, longitude: -122.4194 },
      (async () =>
        new Response(JSON.stringify({ current: { temperature_2m: 12.4, weather_code: 61 }, padding: "x".repeat(2_000) }), {
          status: 200,
          headers: { "Content-Type": "application/json" }
        })) as typeof fetch,
      config
    );
    const unreadable = await fetchChallengeWeatherContext(
      { latitude: 37.7749, longitude: -122.4194 },
      (async () => ({
        ok: true,
        status: 200,
        json: async () => ({ current: { temperature_2m: 12.4, weather_code: 61 } })
      }) as Response) as typeof fetch,
      config
    );

    assert.deepEqual(weather, { weatherCondition: "rain", temperatureC: 12 });
    assert.equal(requestedUrls.length, 1);
    assert.match(requestedUrls[0], /latitude=37\.8/);
    assert.match(requestedUrls[0], /longitude=-122\.4/);
    assert.equal(requestedUrls[0].includes("37.7749"), false);
    assert.equal(requestedUrls[0].includes("-122.4194"), false);
    assert.deepEqual(oversized, { weatherCondition: null, temperatureC: null });
    assert.deepEqual(unreadable, { weatherCondition: null, temperatureC: null });
  });

  await asyncTest("remote analytics transport sends aggregate-only payloads after consent", async () => {
    const previousEndpoint = process.env.EXPO_PUBLIC_ANALYTICS_ENDPOINT;
    process.env.EXPO_PUBLIC_ANALYTICS_ENDPOINT = "https://analytics.freed.app/api/analytics";
    try {
    const state = recordChallengeCompletion(
      recordDailyCheckIn(
        recordBlockingAttempt(
          createDefaultRecoveryState(),
          {
            ...createBlockingAttempt("https://pornhub.com/watch?token=secret", "browser"),
            detectedAt: "2026-05-12T22:15:00.000Z"
          }
        ),
        {
          mood: "stressed",
          urgeLevel: 4,
          sleepQuality: 2,
          reflection: "Private reflection with https://private.example.com/raw-note?secret=true"
        },
        "2026-05-12T08:00:00.000Z"
      ),
      challengeLibrary[0],
      "2026-05-12T22:30:00.000Z",
      "pornhub.com",
      "helped"
    );
    const controls = {
      ...createDefaultAnalyticsSharingControls(),
      enabled: true,
      userOptedInAt: "2026-05-13T09:00:00.000Z",
      consentVersion: ANALYTICS_CONSENT_VERSION,
      endpointUrl: "https://analytics.freed.app/api/analytics",
      dataRetentionDays: 14
    };
    let capturedInput = "";
    let capturedBody = "";
    const analyticsResponsePayload = { accepted: true, status: "ok", provider: "custom" };
    const result = await sendGatedAnalyticsPayload(state, controls, {
      day: "2026-05-13T12:00:00.000Z",
      fetcher: async (input, init) => {
        capturedInput = input;
        capturedBody = String(init?.body ?? "");
        return {
          ok: true,
          status: 200,
          text: async () => JSON.stringify(analyticsResponsePayload),
          json: async () => analyticsResponsePayload
        };
      }
    });
    const body = JSON.parse(capturedBody);
    const text = JSON.stringify(body);

    assert.equal(result.sent, true);
    assert.equal(result.accepted, true);
    assert.equal(result.status, "ok");
    assert.equal(capturedInput, controls.endpointUrl);
    assert.equal(body.snapshot.schemaVersion, "aggregate-v5");
    assert.equal(body.snapshot.behavior.browserInterceptions, 1);
    assert.equal(body.snapshot.productionMetrics.blockedAttempts, 1);
    assert.equal(
      body.snapshot.productionMetrics.blockedAttemptSourceBreakdown.reduce((total, bucket) => total + bucket.count, 0),
      1
    );
    assert.equal(body.snapshot.productionMetrics.blockedAttemptSourceBreakdown.find((bucket) => bucket.source === "browser")?.count, 1);
    assert.equal(body.snapshot.productionMetrics.challengeCompletions, 1);
    assert.equal(body.snapshot.productionMetrics.hourlyUrgePattern.length, 24);
    assert.equal(body.snapshot.productionMetrics.hourlyUrgePattern.reduce((total, bucket) => total + bucket.count, 0), 2);
    assert.equal(body.snapshot.productionMetrics.challengeSuccessRate, 100);
    assert.equal(
      body.snapshot.productionMetrics.challengeSuccessByCategory.reduce((total, category) => total + category.completed, 0),
      1
    );
    assert.equal(body.snapshot.privacy.aggregateOnly, true);
    assert.equal(text.includes("pornhub.com"), false);
    assert.equal(text.includes("private.example.com"), false);
    assert.equal(text.includes("raw-note"), false);
    assert.equal(text.includes("secret=true"), false);
    assert.equal(text.includes("Private reflection"), false);

    const unsafeReasonResult = await sendGatedAnalyticsPayload(state, controls, {
      day: "2026-05-13T12:00:00.000Z",
      fetcher: async () =>
        ({
          ok: false,
          status: 502,
          text: async () =>
            JSON.stringify({
              accepted: false,
              status: "error",
              provider: "custom",
              reason: "Provider echoed https://private.example.com/raw?token=secret and access_token=abc123."
            })
        }) as Pick<Response, "ok" | "status" | "text">
    });
    assert.equal(unsafeReasonResult.accepted, false);
    assert.equal(unsafeReasonResult.status, "error");
    assert.equal(unsafeReasonResult.reason?.includes("private.example.com"), false);
    assert.equal(unsafeReasonResult.reason?.includes("access_token=abc123"), false);
    assert.match(unsafeReasonResult.reason ?? "", /\[redacted-link\]|\[redacted-secret\]/);

    let futureConsentFetchCalled = false;
    const futureConsent = await sendGatedAnalyticsPayload(
      state,
      {
        ...controls,
        userOptedInAt: "2999-01-01T09:00:00.000Z"
      },
      {
        day: "2026-05-13T12:00:00.000Z",
        fetcher: async () => {
          futureConsentFetchCalled = true;
          throw new Error("future consent must block before network");
        }
      }
    );
    assert.equal(futureConsent.sent, false);
    assert.equal(futureConsent.accepted, false);
    assert.equal(futureConsent.status, "blocked");
    assert.equal(futureConsentFetchCalled, false);
    assert.ok(futureConsent.readiness.gaps.includes("analytics-consent-time-in-future"));

    const timedOut = await sendGatedAnalyticsPayload(state, controls, {
      day: "2026-05-13T12:00:00.000Z",
      timeoutMs: 50,
      fetcher: async () =>
        new Promise<Pick<Response, "ok" | "json" | "status">>(() => {
          /* Simulates a stalled aggregate analytics endpoint */
        })
    });
    assert.equal(timedOut.sent, true);
    assert.equal(timedOut.accepted, false);
    assert.equal(timedOut.status, "error");
    assert.match(timedOut.reason ?? "", /timed out/);
    } finally {
      restoreEnv("EXPO_PUBLIC_ANALYTICS_ENDPOINT", previousEndpoint);
    }
  });

