  await asyncTest("AI API fallback reasons redact provider diagnostics", async () => {
    const previousKeys = snapshotAiServerKeys();
    const previousFetch = globalThis.fetch;
    const capturedAudits: AiBackendAuditEvent[] = [];

    configureAiBackendAuditProvider((event) => {
      capturedAudits.push(event);
      return {
        recorded: true,
        provider: "custom",
        status: "ok",
        tableName: "ai_backend_events"
      };
    });

    try {
      clearAiServerKeys();
      process.env.GEMINI_API_KEY = "AIzaSyRuntimeProviderKey1234567890abcd";
      process.env.GEMINI_MODEL = "gemini-2.5-flash";
      globalThis.fetch = (async () => {
        throw new Error("Provider echoed https://private.example.com/raw?token=secret and access_token=abc123.");
      }) as typeof fetch;

      const claraRoute = await import("../app/api/clara+api");
      const challengeRoute = await import("../app/api/challenges+api");
      const retentionRoute = await import("../app/api/retention+api");

      const claraResponse = await claraRoute.POST(
        new Request("http://localhost/api/clara", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify(buildCoachRequest("I need help", { attempts: [] }))
        })
      );
      const challengeResponse = await challengeRoute.POST(
        new Request("http://localhost/api/challenges", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify(buildChallengeGenerationRequest({ streakDays: 4, premium: false, attemptsToday: 1, mood: "stressed", hour: 23 }))
        })
      );
      const retentionResponse = await retentionRoute.POST(
        new Request("http://localhost/api/retention", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify(buildRetentionRequest(createDefaultRecoveryState()))
        })
      );

      const payloads = [
        (await claraResponse.json()) as { provider?: string; status?: string; reason?: string },
        (await challengeResponse.json()) as { provider?: string; status?: string; reason?: string },
        (await retentionResponse.json()) as { provider?: string; status?: string; reason?: string }
      ];
      const expectedReasons = ["CLARA backend fallback.", "Challenge backend fallback.", "Retention backend fallback."];

      assert.equal(claraResponse.status, 200);
      assert.equal(challengeResponse.status, 200);
      assert.equal(retentionResponse.status, 200);
      for (const [index, payload] of payloads.entries()) {
        assert.equal(payload.provider, "fallback");
        assert.equal(payload.status, "fallback");
        assert.equal(payload.reason, expectedReasons[index]);
        assert.equal((payload.reason ?? "").includes("private.example.com"), false);
        assert.equal((payload.reason ?? "").includes("token=secret"), false);
        assert.equal((payload.reason ?? "").includes("access_token=abc123"), false);
        assert.equal((payload.reason ?? "").includes("[redacted"), false);
        assert.equal(/https?:\/\//i.test(payload.reason ?? ""), false);
      }

      const auditText = JSON.stringify(capturedAudits);
      assert.equal(capturedAudits.length, 3);
      assert.ok(capturedAudits.every((event) => event.provider === "fallback"));
      assert.equal(auditText.includes("private.example.com"), false);
      assert.equal(auditText.includes("token=secret"), false);
      assert.equal(auditText.includes("access_token=abc123"), false);
      assert.equal(/https?:\/\//i.test(auditText), false);
    } finally {
      restoreAiServerKeys(previousKeys);
      globalThis.fetch = previousFetch;
      configureAiBackendAuditProvider(null);
    }
  });

