  await asyncTest("production native purchases fail closed without server verification", async () => {
    const previous = {
      mode: process.env.EXPO_PUBLIC_MONETIZATION_MODE,
      nodeEnv: process.env.NODE_ENV,
      purchaseVerifyEndpoint: process.env.EXPO_PUBLIC_PURCHASE_VERIFY_ENDPOINT
    };
    let purchaseCalls = 0;
    let restoreCalls = 0;
    configureNativeMonetizationProvider({
      purchasePremiumPlan: async (plan) => {
        purchaseCalls += 1;
        return {
          status: "purchased",
          premium: true,
          provider: "native",
          message: `${plan.productId} purchased through test provider.`,
          planId: plan.id
        };
      },
      restorePremiumPurchases: async (plans) => {
        restoreCalls += 1;
        return {
          status: "purchased",
          premium: true,
          provider: "native",
          message: "Native restore found an active entitlement.",
          planId: plans[0].id
        };
      }
    });

    try {
      process.env.NODE_ENV = "production";
      process.env.EXPO_PUBLIC_MONETIZATION_MODE = "native";
      delete process.env.EXPO_PUBLIC_PURCHASE_VERIFY_ENDPOINT;

      const missingEndpoint = await purchasePremiumPlan("yearly", { platform: "ios" });
      const missingRestoreEndpoint = await restorePremiumPurchases({ platform: "ios" });
      assert.equal(missingEndpoint.status, "failed");
      assert.equal(missingEndpoint.premium, false);
      assert.match(missingEndpoint.message, /server purchase verification endpoint/);
      assert.equal(missingRestoreEndpoint.status, "failed");
      assert.equal(missingRestoreEndpoint.premium, false);
      assert.equal(purchaseCalls, 0);
      assert.equal(restoreCalls, 0);

      process.env.EXPO_PUBLIC_PURCHASE_VERIFY_ENDPOINT = "https://api.freedrecovery.app/api/purchases/verify?token=secret";
      const unsafeEndpoint = await purchasePremiumPlan("yearly", { platform: "ios" });
      assert.equal(unsafeEndpoint.premium, false);
      assert.equal(purchaseCalls, 0);

      process.env.EXPO_PUBLIC_PURCHASE_VERIFY_ENDPOINT = "https://api.freedrecovery.app/api/purchases/verify";
      const verifiedConfigPurchase = await purchasePremiumPlan("yearly", { platform: "ios" });
      const verifiedConfigRestore = await restorePremiumPurchases({ platform: "ios" });
      assert.equal(verifiedConfigPurchase.premium, true);
      assert.equal(verifiedConfigRestore.premium, true);
      assert.equal(purchaseCalls, 1);
      assert.equal(restoreCalls, 1);
    } finally {
      restoreEnv("EXPO_PUBLIC_MONETIZATION_MODE", previous.mode);
      restoreEnv("NODE_ENV", previous.nodeEnv);
      restoreEnv("EXPO_PUBLIC_PURCHASE_VERIFY_ENDPOINT", previous.purchaseVerifyEndpoint);
      configureNativeMonetizationProvider(null);
    }
  });

